import tools.isa_standard_completion as ledger


def test_standard_isa_completion_has_no_partial_or_gap():
    counts = ledger.status_counts()
    assert counts[ledger.CLOSED] == 164
    assert counts[ledger.PARTIAL] == 0
    assert counts[ledger.GAP] == 0
    assert counts[ledger.NON_INSTRUCTION] == 2


def test_standard_isa_completion_rows_are_closed_or_non_instruction_only():
    open_rows = [
        row for row in ledger.ROWS
        if row["status"] not in {ledger.CLOSED, ledger.NON_INSTRUCTION}
    ]
    assert open_rows == []


def test_closed_standard_rows_have_runtime_non_pending_evidence():
    forbidden = ("pending", "partial", "smoke")
    bad_rows = []
    for row in ledger.ROWS:
        if row["status"] != ledger.CLOSED:
            continue
        evidence = row["evidence"].lower()
        closure = row["closure"].lower()
        if closure != "runtime" or any(token in evidence for token in forbidden):
            bad_rows.append(row)
    assert bad_rows == []


def test_standard_isa_completion_rows_are_unique_and_documented():
    seen = set()
    duplicate_rows = []
    undocumented_rows = []
    for row in ledger.ROWS:
        key = (row["extension"], row["instruction"])
        if key in seen:
            duplicate_rows.append(row)
        seen.add(key)
        if not row["closure"] or not row["evidence"]:
            undocumented_rows.append(row)
    assert duplicate_rows == []
    assert undocumented_rows == []


def test_standard_isa_reports_are_in_sync_with_ledger():
    csv_text = ledger.CSV_PATH.read_text()
    md_text = ledger.MD_PATH.read_text()
    for row in ledger.ROWS:
        assert row["instruction"] in csv_text
        assert row["status"] in csv_text
        assert row["evidence"] in csv_text
        assert row["instruction"] in md_text
        assert row["status"] in md_text


def test_standard_isa_completion_extension_row_counts_are_stable():
    expected_counts = {
        "RV32I": 41,
        "M": 8,
        "A": 11,
        "F": 26,
        "D": 26,
        "C": 27,
        "Zbb": 18,
        "Zicsr": 6,
        "Zifencei": 1,
        "Zam": 1,
        "Ztso": 1,
    }
    actual_counts = {}
    for row in ledger.ROWS:
        actual_counts[row["extension"]] = actual_counts.get(row["extension"], 0) + 1
    assert actual_counts == expected_counts


def test_standard_isa_csv_report_matches_ledger_rows_exactly():
    import csv

    with ledger.CSV_PATH.open(newline="") as f:
        report_rows = list(csv.DictReader(f))
    expected_rows = [
        {
            "extension": row["extension"],
            "instruction": row["instruction"],
            "status": row["status"],
            "closure": row["closure"],
            "evidence": row["evidence"],
        }
        for row in ledger.ROWS
    ]
    assert report_rows == expected_rows


def test_standard_isa_completion_status_counts_are_total_and_known():
    allowed_statuses = {ledger.CLOSED, ledger.PARTIAL, ledger.GAP, ledger.NON_INSTRUCTION}
    row_statuses = [row["status"] for row in ledger.ROWS]
    assert set(row_statuses) <= allowed_statuses
    counts = ledger.status_counts()
    assert set(counts) == allowed_statuses
    assert sum(counts.values()) == len(ledger.ROWS)
    assert counts[ledger.CLOSED] + counts[ledger.NON_INSTRUCTION] == len(ledger.ROWS)


def test_standard_isa_non_instruction_rows_are_metadata_only():
    non_instruction_rows = [
        row for row in ledger.ROWS
        if row["status"] == ledger.NON_INSTRUCTION
    ]
    assert non_instruction_rows == [
        {
            "extension": "Zam",
            "instruction": "(no new instruction encodings)",
            "status": ledger.NON_INSTRUCTION,
            "closure": "metadata",
            "evidence": "Extension affects memory model/atomicity rules rather than adding distinct instruction mnemonics",
        },
        {
            "extension": "Ztso",
            "instruction": "(no new instruction encodings)",
            "status": ledger.NON_INSTRUCTION,
            "closure": "metadata",
            "evidence": "Extension affects memory model/atomicity rules rather than adding distinct instruction mnemonics",
        },
    ]


def test_standard_isa_markdown_report_has_one_table_row_per_ledger_row():
    md_lines = ledger.MD_PATH.read_text().splitlines()
    header = "| Extension | Instruction | Status | Closure | Evidence |"
    start = md_lines.index(header) + 2
    table_rows = [line for line in md_lines[start:] if line.startswith("| ")]
    assert len(table_rows) == len(ledger.ROWS)
    for row in ledger.ROWS:
        expected_fragment = f"| {row['extension']} | {row['instruction']} | {row['status']} | {row['closure']} |"
        assert any(line.startswith(expected_fragment) for line in table_rows)


def test_standard_isa_reports_have_no_open_instruction_rows():
    csv_text = ledger.CSV_PATH.read_text()
    md_lines = ledger.MD_PATH.read_text().splitlines()
    detail_start = md_lines.index("| Extension | Instruction | Status | Closure | Evidence |") + 2
    detail_rows = md_lines[detail_start:]
    assert ",PARTIAL," not in csv_text
    assert ",GAP," not in csv_text
    assert not any("| PARTIAL |" in line for line in detail_rows)
    assert not any("| GAP |" in line for line in detail_rows)


def test_star_extension_alias_keeps_standard_completion_extensions_reachable():
    from rtl.rv12_core import normalize_extension_spec

    star_extensions = normalize_extension_spec("RV32I+GC+*")
    expected_extensions = {
        "RV32I", "GC", "M", "A", "B", "F", "D", "C", "ZICSR", "ZIFENCEI", "ZICOND"
    }
    assert expected_extensions <= star_extensions


def test_gc_extension_alias_isolated_from_standard_extensions():
    from rtl.rv12_core import normalize_extension_spec

    gc_extensions = normalize_extension_spec("RV32I+GC")
    assert gc_extensions == {"RV32I", "GC"}


