def test_rv32i_gc_instruction_set_is_fully_closed_runtime():
    gc_extensions = {"RV32I", "M", "A", "F", "D", "C", "Zicsr", "Zifencei"}
    gc_rows = [row for row in ledger.ROWS if row["extension"] in gc_extensions]
    assert len(gc_rows) == 146
    assert all(row["status"] == ledger.CLOSED for row in gc_rows)
    assert all(row["closure"] == "runtime" for row in gc_rows)
    assert {row["extension"] for row in gc_rows} == gc_extensions


