def test_standard_rows_have_exact_status_closure_pairs():
    allowed_pairs = {
        ledger.CLOSED: "runtime",
        ledger.NON_INSTRUCTION: "metadata",
    }
    assert all(row["closure"] == allowed_pairs[row["status"]] for row in ledger.ROWS)
    assert {row["status"] for row in ledger.ROWS} == set(allowed_pairs)


def test_rv32i_gc_star_full_standard_ledger_is_exactly_partitioned():
    standard_extensions = {
        "RV32I",
        "M",
        "A",
        "F",
        "D",
        "C",
        "Zbb",
        "Zicsr",
        "Zifencei",
        "Zam",
        "Ztso",
    }
    rows = [row for row in ledger.ROWS if row["extension"] in standard_extensions]
    assert len(rows) == 166
    assert len([row for row in rows if row["status"] == ledger.CLOSED]) == 164
    assert len([row for row in rows if row["status"] == ledger.NON_INSTRUCTION]) == 2
    assert all(row["closure"] in {"runtime", "metadata"} for row in rows)


