def test_generated_csv_status_closure_pairs_are_exact():
    import csv
    from pathlib import Path

    with Path("reports/isa_standard_completion.csv").open(newline="") as handle:
        rows = list(csv.DictReader(handle))
    pairs = {}
    for row in rows:
        pair = (row["status"], row["closure"])
        pairs[pair] = pairs.get(pair, 0) + 1
    assert pairs == {
        (ledger.CLOSED, "runtime"): 164,
        (ledger.NON_INSTRUCTION, "metadata"): 2,
    }


