def test_generated_markdown_row_order_matches_authoritative_ledger():
    from pathlib import Path

    report = Path("reports/isa_standard_completion.md").read_text()
    detail_lines = [
        line
        for line in report.splitlines()
        if line.startswith("|") and ("| runtime |" in line or "| metadata |" in line)
    ]
    actual_keys = []
    for line in detail_lines:
        cells = [cell.strip() for cell in line.strip().strip("|").split("|")]
        actual_keys.append((cells[0], cells[1]))
    expected_keys = [(row["extension"], row["instruction"]) for row in ledger.ROWS]
    assert actual_keys == expected_keys


def test_generated_csv_and_markdown_rows_are_exactly_equivalent():
    import csv
    from pathlib import Path

    with Path("reports/isa_standard_completion.csv").open(newline="") as handle:
        csv_rows = [
            (
                row["extension"],
                row["instruction"],
                row["status"],
                row["closure"],
                row["evidence"],
            )
            for row in csv.DictReader(handle)
        ]
    report = Path("reports/isa_standard_completion.md").read_text()
    markdown_rows = []
    for line in report.splitlines():
        if line.startswith("|") and ("| runtime |" in line or "| metadata |" in line):
            cells = [cell.strip() for cell in line.strip().strip("|").split("|")]
            markdown_rows.append(tuple(cells[:5]))
    assert markdown_rows == csv_rows


def test_executable_and_metadata_rows_are_strictly_separated():
    for row in ledger.ROWS:
        if row["status"] == ledger.CLOSED:
            assert row["instruction"] != "(no new instruction encodings)"
            assert row["extension"] not in {"Zam", "Ztso"}
        elif row["status"] == ledger.NON_INSTRUCTION:
            assert row["instruction"] == "(no new instruction encodings)"
            assert row["extension"] in {"Zam", "Ztso"}
        else:
            raise AssertionError(f"unexpected status: {row['status']}")


def test_completion_status_constants_are_stable():
    assert ledger.CLOSED == "CLOSED"
    assert ledger.PARTIAL == "PARTIAL"
