def test_completion_cli_outputs_exact_status_summary():
    import subprocess
    from pathlib import Path

    result = subprocess.run(
        ["python3", "tools/isa_standard_completion.py"],
        check=True,
        capture_output=True,
        text=True,
    )
    assert "CLOSED=164 PARTIAL=0 GAP=0 NON_INSTRUCTION=2" in result.stdout
    assert Path("reports/isa_standard_completion.csv").is_file()
    assert Path("reports/isa_standard_completion.md").is_file()


def test_completion_cli_report_generation_is_deterministic():
    import subprocess
    from pathlib import Path

    csv_path = Path("reports/isa_standard_completion.csv")
    md_path = Path("reports/isa_standard_completion.md")
