def test_generated_markdown_status_and_closure_values_are_canonical():
    from pathlib import Path

    report = Path("reports/isa_standard_completion.md").read_text()
    detail_rows = [
        line
        for line in report.splitlines()
        if line.startswith("|") and ("| runtime |" in line or "| metadata |" in line)
    ]
    assert len(detail_rows) == 166
    statuses = set()
    closures = set()
    for line in detail_rows:
        cells = [cell.strip() for cell in line.strip().strip("|").split("|")]
        statuses.add(cells[2])
        closures.add(cells[3])
    assert statuses == {ledger.CLOSED, ledger.NON_INSTRUCTION}
    assert closures == {"runtime", "metadata"}
    assert ledger.PARTIAL not in statuses
    assert ledger.GAP not in statuses


