def test_generated_csv_profile_counts_are_exact():
    import csv
    from pathlib import Path

    rv32i_gc_extensions = {"RV32I", "M", "A", "F", "D", "C", "Zicsr", "Zifencei"}
    rv32i_gc_zbb_extensions = rv32i_gc_extensions | {"Zbb"}
    with Path("reports/isa_standard_completion.csv").open(newline="") as handle:
        rows = list(csv.DictReader(handle))
    rv32i_gc_rows = [row for row in rows if row["extension"] in rv32i_gc_extensions]
