    assert len(rv32i_gc_rows) == 146
    assert len(rv32i_gc_zbb_rows) == 164
    assert all(row["status"] == ledger.CLOSED and row["closure"] == "runtime" for row in rv32i_gc_rows)
    assert all(row["status"] == ledger.CLOSED and row["closure"] == "runtime" for row in rv32i_gc_zbb_rows)


