def test_authoritative_ledger_boundary_sentinels_are_stable():
    assert ledger.ROWS[0]["extension"] == "RV32I"
    assert ledger.ROWS[0]["instruction"] == "LUI"
    assert ledger.ROWS[0]["status"] == ledger.CLOSED
    assert ledger.ROWS[0]["closure"] == "runtime"
    assert "test" in ledger.ROWS[0]["evidence"].lower()

    assert ledger.ROWS[-1]["extension"] == "Ztso"
    assert ledger.ROWS[-1]["instruction"] == "(no new instruction encodings)"
    assert ledger.ROWS[-1]["status"] == ledger.NON_INSTRUCTION
    assert ledger.ROWS[-1]["closure"] == "metadata"


def test_generated_reports_boundary_sentinels_match_ledger():
    import csv
    from pathlib import Path

    with Path("reports/isa_standard_completion.csv").open(newline="") as handle:
        csv_rows = list(csv.DictReader(handle))
    assert (csv_rows[0]["extension"], csv_rows[0]["instruction"]) == ("RV32I", "LUI")
    assert (csv_rows[-1]["extension"], csv_rows[-1]["instruction"]) == ("Ztso", "(no new instruction encodings)")

    report = Path("reports/isa_standard_completion.md").read_text()
    markdown_rows = []
    for line in report.splitlines():
        if line.startswith("|") and ("| runtime |" in line or "| metadata |" in line):
            cells = [cell.strip() for cell in line.strip().strip("|").split("|")]
            markdown_rows.append(cells)
    assert (markdown_rows[0][0], markdown_rows[0][1]) == ("RV32I", "LUI")
    assert (markdown_rows[-1][0], markdown_rows[-1][1]) == ("Ztso", "(no new instruction encodings)")


