    summary_total = 0
    for line in markdown.splitlines():
        if line.startswith("|") and ("| CLOSED |" in line or "| NON_INSTRUCTION |" in line):
            cells = [cell.strip() for cell in line.strip().strip("|").split("|")]
            if len(cells) == 2 and cells[1].isdigit():
                summary_total += int(cells[1])

    markdown_detail_rows = 0
    for line in markdown.splitlines():
        if line.startswith("|") and ("| CLOSED |" in line or "| NON_INSTRUCTION |" in line):
            cells = [cell.strip() for cell in line.strip().strip("|").split("|")]
            if len(cells) == 5 and cells[2] in {ledger.CLOSED, ledger.NON_INSTRUCTION}:
                markdown_detail_rows += 1

    with Path("reports/isa_standard_completion.csv").open(newline="") as handle:
        csv_detail_rows = sum(1 for _ in csv.DictReader(handle))

    assert summary_total == markdown_detail_rows == csv_detail_rows == len(ledger.ROWS) == 166


