def test_ledger_csv_markdown_extension_block_boundaries_are_identical():
    import csv
    from pathlib import Path

    expected_boundaries = {
        "RV32I": ("LUI", "x0 invariant"),
        "M": ("MUL", "REMU"),
        "A": ("LR.W", "AMOMAXU.W"),
        "F": ("FLW", "FMV.W.X"),
        "D": ("FLD", "FCVT.D.WU"),
        "C": ("C.ADDI4SPN", "C.SWSP"),
        "Zbb": ("ANDN", "REV8"),
        "Zicsr": ("CSRRW", "CSRRCI"),
        "Zifencei": ("FENCE.I", "FENCE.I"),
        "Zam": ("(no new instruction encodings)", "(no new instruction encodings)"),
        "Ztso": ("(no new instruction encodings)", "(no new instruction encodings)"),
    }

    def block_boundaries(rows):
        boundaries = {}
        for row in rows:
            extension = row["extension"]
            instruction = row["instruction"]
            if extension not in boundaries:
                boundaries[extension] = [instruction, instruction]
            else:
                boundaries[extension][1] = instruction
        return {extension: tuple(boundary) for extension, boundary in boundaries.items()}

    ledger_boundaries = block_boundaries(ledger.ROWS)
    with Path("reports/isa_standard_completion.csv").open(newline="") as handle:
        csv_boundaries = block_boundaries(list(csv.DictReader(handle)))

    markdown_rows = []
    for line in Path("reports/isa_standard_completion.md").read_text().splitlines():
        if line.startswith("|") and ("| CLOSED |" in line or "| NON_INSTRUCTION |" in line):
            cells = [cell.strip() for cell in line.strip().strip("|").split("|")]
            if len(cells) == 5 and cells[2] in {ledger.CLOSED, ledger.NON_INSTRUCTION}:
                markdown_rows.append({"extension": cells[0], "instruction": cells[1]})
    markdown_boundaries = block_boundaries(markdown_rows)

    assert ledger_boundaries == csv_boundaries == markdown_boundaries == expected_boundaries


