def test_ledger_csv_markdown_gc_profile_complement_order_is_identical():
    import csv
    from pathlib import Path

    gc_extensions = {"RV32I", "M", "A", "F", "D", "C", "Zicsr", "Zifencei"}
    expected_extension_order = ["Zbb", "Zam", "Ztso"]

    def complement_rows(rows):
        return [
            row
            for row in rows
            if not (row["extension"] in gc_extensions and row["closure"] == "runtime")
        ]

    def extension_order(rows):
        order = []
        for row in rows:
            extension = row["extension"]
            if not order or order[-1] != extension:
                order.append(extension)
        return order

    with Path("reports/isa_standard_completion.csv").open(newline="") as handle:
        csv_rows = list(csv.DictReader(handle))

    markdown_rows = []
    for line in Path("reports/isa_standard_completion.md").read_text().splitlines():
        if line.startswith("|") and ("| runtime |" in line or "| metadata |" in line):
            cells = [cell.strip() for cell in line.strip().strip("|").split("|")]
            if len(cells) == 5 and cells[3] in {"runtime", "metadata"}:
                markdown_rows.append({
                    "extension": cells[0],
                    "instruction": cells[1],
                    "closure": cells[3],
                })

    ledger_complement = complement_rows(ledger.ROWS)
    csv_complement = complement_rows(csv_rows)
    markdown_complement = complement_rows(markdown_rows)
    assert extension_order(ledger_complement) == extension_order(csv_complement) == extension_order(markdown_complement) == expected_extension_order
    assert len(ledger_complement) == len(csv_complement) == len(markdown_complement) == 20
    assert (ledger_complement[0]["extension"], ledger_complement[0]["instruction"]) == ("Zbb", "ANDN")
    assert (ledger_complement[-1]["extension"], ledger_complement[-1]["instruction"]) == ("Ztso", "(no new instruction encodings)")


