def test_ledger_csv_markdown_profile_partitions_are_disjoint_and_exhaustive():
    import csv
    from pathlib import Path

    gc_extensions = {"RV32I", "M", "A", "F", "D", "C", "Zicsr", "Zifencei"}
    gc_zbb_extensions = gc_extensions | {"Zbb"}

    def row_key(row):
        return (
            row["extension"],
            row["instruction"],
            row["status"],
            row["closure"],
            row["evidence"],
        )

    def runtime_profile_keys(rows, extensions):
        return {
            row_key(row)
            for row in rows
            if row["extension"] in extensions and row["closure"] == "runtime"
        }

    def complement_keys(rows, extensions):
        return {
            row_key(row)
            for row in rows
            if not (row["extension"] in extensions and row["closure"] == "runtime")
        }

    def assert_partition(rows, extensions, profile_count, complement_count):
        all_keys = {row_key(row) for row in rows}
        profile = runtime_profile_keys(rows, extensions)
        complement = complement_keys(rows, extensions)
        assert not (profile & complement)
        assert profile | complement == all_keys
        assert len(profile) == profile_count
        assert len(complement) == complement_count
        assert len(all_keys) == 166

    with Path("reports/isa_standard_completion.csv").open(newline="") as handle:
        csv_rows = list(csv.DictReader(handle))

    markdown_rows = []
    for line in Path("reports/isa_standard_completion.md").read_text().splitlines():
        if line.startswith("|") and ("| runtime |" in line or "| metadata |" in line):
            cells = [cell.strip() for cell in line.strip().strip("|").split("|")]
            if len(cells) == 5 and cells[3] in {"runtime", "metadata"}:
                markdown_rows.append({
                    "extension": cells[0],
                    "instruction": cells[1],
                    "status": cells[2],
                    "closure": cells[3],
                    "evidence": cells[4],
                })

    for rows in (ledger.ROWS, csv_rows, markdown_rows):
        assert_partition(rows, gc_extensions, 146, 20)
        assert_partition(rows, gc_zbb_extensions, 164, 2)


