def test_completion_cli_stdout_totals_match_generated_artifacts():
    import csv
    import subprocess
    from collections import Counter
    from pathlib import Path

    result = subprocess.run(
        ["python3", "tools/isa_standard_completion.py"],
        check=True,
        capture_output=True,
        text=True,
    )
    assert "CLOSED=164 PARTIAL=0 GAP=0 NON_INSTRUCTION=2" in result.stdout

    expected_status_counts = Counter({
        ledger.CLOSED: 164,
        ledger.NON_INSTRUCTION: 2,
    })
    ledger_counts = Counter(row["status"] for row in ledger.ROWS)
    with Path("reports/isa_standard_completion.csv").open(newline="") as handle:
        csv_counts = Counter(row["status"] for row in csv.DictReader(handle))

    markdown_counts = Counter()
    for line in Path("reports/isa_standard_completion.md").read_text().splitlines():
        if line.startswith("|") and ("| CLOSED |" in line or "| NON_INSTRUCTION |" in line):
            cells = [cell.strip() for cell in line.strip().strip("|").split("|")]
            if len(cells) == 5 and cells[2] in {ledger.CLOSED, ledger.NON_INSTRUCTION}:
                markdown_counts[cells[2]] += 1

    assert ledger_counts == csv_counts == markdown_counts == expected_status_counts


