    assert len(runtime_rows) == 164
    assert all(parts[3] == "CLOSED" for parts in runtime_rows)
    assert all(parts[2] != "(no new instruction encodings)" for parts in runtime_rows)
    assert all(parts[2].strip() == parts[2] for parts in runtime_rows)
    assert all(parts[5].strip() == parts[5] for parts in runtime_rows)
    assert all("distinct instruction mnemonics" not in parts[5] for parts in runtime_rows)

