def test_completion_report_markdown_summary_counts_parse_to_csv_status_counts():
    import csv
    import subprocess
    from collections import Counter
    from pathlib import Path

    subprocess.run(
        ["python3", "tools/isa_standard_completion.py"],
        check=True,
        capture_output=True,
    )
    with Path("reports/isa_standard_completion.csv").open(newline="", encoding="utf-8") as handle:
        csv_counts = Counter(row["status"] for row in csv.DictReader(handle))
    report_lines = Path("reports/isa_standard_completion.md").read_text(encoding="utf-8").splitlines()
    summary_index = report_lines.index("| Status | Count |")
    summary_counts = {}
    for line in report_lines[summary_index + 2 : summary_index + 6]:
        _, status, count, _ = [cell.strip() for cell in line.split("|")]
        summary_counts[status] = int(count)
    assert summary_counts == {
        "CLOSED": csv_counts["CLOSED"],
        "PARTIAL": csv_counts["PARTIAL"],
        "GAP": csv_counts["GAP"],
        "NON_INSTRUCTION": csv_counts["NON_INSTRUCTION"],
    }
    assert summary_counts == {
        "CLOSED": 164,
        "PARTIAL": 0,
        "GAP": 0,
        "NON_INSTRUCTION": 2,
    }

