def test_completion_report_glob_stdout_identity_mapping_is_idempotent_across_runs():
    import hashlib
    import subprocess
    from pathlib import Path

    def collect_identity_mapping():
        result = subprocess.run(
            ["python3", "tools/isa_standard_completion.py"],
            check=True,
            capture_output=True,
            text=True,
        )
        stdout_artifacts = {
            path.as_posix(): (path.name, path.suffix, hashlib.sha256(path.read_bytes()).hexdigest())
            for path in (
                Path(text)
                for text in result.stdout.splitlines()[0].removeprefix("wrote ").split(" and ")
            )
        }
        glob_artifacts = {
            path.as_posix(): (path.name, path.suffix, hashlib.sha256(path.read_bytes()).hexdigest())
            for path in sorted(Path("reports").glob("isa_standard_completion.*"))
            if path.is_file()
        }
        assert glob_artifacts == stdout_artifacts
        return glob_artifacts

