def test_completion_report_identity_mapped_csv_preserves_status_counts():
    import csv
    import subprocess
    from collections import Counter
    from pathlib import Path

    result = subprocess.run(
        ["python3", "tools/isa_standard_completion.py"],
        check=True,
        capture_output=True,
        text=True,
    )
    stdout_paths = [
        Path(text)
        for text in result.stdout.splitlines()[0].removeprefix("wrote ").split(" and ")
    ]
    glob_paths = [
        path
        for path in sorted(Path("reports").glob("isa_standard_completion.*"))
        if path.is_file()
    ]
    assert glob_paths == stdout_paths
    csv_path = next(path for path in glob_paths if path.suffix == ".csv")
    with csv_path.open(newline="", encoding="utf-8") as handle:
        status_counts = Counter(row["status"] for row in csv.DictReader(handle))
    assert status_counts == {
        "CLOSED": 164,
        "NON_INSTRUCTION": 2,
    }
    assert status_counts["PARTIAL"] == 0
    assert status_counts["GAP"] == 0

def test_completion_report_identity_mapped_markdown_preserves_summary_counts():
    import subprocess
