    markdown_path = next(path for path in glob_paths if path.suffix == ".md")
    report_lines = markdown_path.read_text(encoding="utf-8").splitlines()
    summary_index = report_lines.index("| Status | Count |")
    summary_counts = {}
    for line in report_lines[summary_index + 2 : summary_index + 6]:
        _, status, count, _ = [cell.strip() for cell in line.split("|")]
        summary_counts[status] = int(count)
