def test_completion_report_identity_mapped_extension_blocks_are_contiguous_and_counted():
    import csv
    import subprocess
    from pathlib import Path

    result = subprocess.run(
        ["python3", "tools/isa_standard_completion.py"],
        check=True,
        capture_output=True,
        text=True,
    )
    stdout_paths = [
        Path(text)
        for text in result.stdout.splitlines()[0].removeprefix("wrote ").split(" and ")
    ]
    glob_paths = [
        path
        for path in sorted(Path("reports").glob("isa_standard_completion.*"))
        if path.is_file()
    ]
    assert glob_paths == stdout_paths
    csv_path = next(path for path in glob_paths if path.suffix == ".csv")
    markdown_path = next(path for path in glob_paths if path.suffix == ".md")
    with csv_path.open(newline="", encoding="utf-8") as handle:
        csv_extensions = [row["extension"] for row in csv.DictReader(handle)]
    report_lines = markdown_path.read_text(encoding="utf-8").splitlines()
    header_index = report_lines.index("| Extension | Instruction | Status | Closure | Evidence |")
    markdown_extensions = []
    for line in report_lines[header_index + 2 :]:
        if line.startswith("| ") and line.endswith(" |"):
            parts = [cell.strip() for cell in line.split("|")]
            markdown_extensions.append(parts[1])
    assert markdown_extensions == csv_extensions
    expected_counts = {
        "RV32I": 41,
        "M": 8,
        "A": 11,
        "F": 26,
        "D": 26,
        "C": 27,
        "Zbb": 18,
        "Zicsr": 6,
        "Zifencei": 1,
        "Zam": 1,
        "Ztso": 1,
    }
    assert {extension: csv_extensions.count(extension) for extension in expected_counts} == expected_counts
    seen = []
    for extension in csv_extensions:
        if not seen or seen[-1] != extension:
            seen.append(extension)
    assert seen == list(expected_counts)
    assert len(csv_extensions) == sum(expected_counts.values()) == 166

