    report_lines = markdown_path.read_text(encoding="utf-8").splitlines()
    header_index = report_lines.index("| Extension | Instruction | Status | Closure | Evidence |")
    markdown_rows = []
    for line in report_lines[header_index + 2 :]:
        if line.startswith("| ") and line.endswith(" |"):
            parts = [cell.strip() for cell in line.split("|")]
            markdown_rows.append((parts[1], parts[2], parts[3], parts[4]))
    assert markdown_rows == csv_rows
    runtime_extensions = {"RV32I", "M", "A", "F", "D", "C", "Zbb", "Zicsr", "Zifencei"}
    metadata_extensions = {"Zam", "Ztso"}
    assert {row[0] for row in csv_rows} == runtime_extensions | metadata_extensions
    for extension in runtime_extensions:
        extension_rows = [row for row in csv_rows if row[0] == extension]
        assert extension_rows
        assert all(row[2:] == ("CLOSED", "runtime") for row in extension_rows)
        assert all(row[1] != "(no new instruction encodings)" for row in extension_rows)
    for extension in metadata_extensions:
        extension_rows = [row for row in csv_rows if row[0] == extension]
        assert len(extension_rows) == 1
        assert extension_rows[0][1:] == (
            "(no new instruction encodings)",
            "NON_INSTRUCTION",
            "metadata",
        )

