def test_completion_report_identity_mapped_summary_counts_match_row_derived_status_counts():
    import csv
    import subprocess
    from collections import Counter
    from pathlib import Path

    result = subprocess.run(
        ["python3", "tools/isa_standard_completion.py"],
        check=True,
        capture_output=True,
        text=True,
    )
    stdout_paths = [
        Path(text)
        for text in result.stdout.splitlines()[0].removeprefix("wrote ").split(" and ")
    ]
    glob_paths = [
        path
        for path in sorted(Path("reports").glob("isa_standard_completion.*"))
        if path.is_file()
    ]
    assert glob_paths == stdout_paths
    csv_path = next(path for path in glob_paths if path.suffix == ".csv")
    markdown_path = next(path for path in glob_paths if path.suffix == ".md")
    with csv_path.open(newline="", encoding="utf-8") as handle:
        csv_status_counts = Counter(row["status"] for row in csv.DictReader(handle))
    report_lines = markdown_path.read_text(encoding="utf-8").splitlines()
    header_index = report_lines.index("| Extension | Instruction | Status | Closure | Evidence |")
    markdown_status_counts = Counter()
    for line in report_lines[header_index + 2 :]:
        if line.startswith("| ") and line.endswith(" |"):
            parts = [cell.strip() for cell in line.split("|")]
            markdown_status_counts[parts[3]] += 1
    summary_counts = {}
    for line in report_lines[report_lines.index("## Summary") + 1 : report_lines.index("## Policy")]:
        if line.startswith("| ") and line.endswith(" |"):
            parts = [cell.strip() for cell in line.split("|")]
            if parts[1] not in {"Status", "--------"}:
                summary_counts[parts[1]] = int(parts[2])
    expected_counts = {"CLOSED": 164, "PARTIAL": 0, "GAP": 0, "NON_INSTRUCTION": 2}
    assert summary_counts == expected_counts
    assert dict(csv_status_counts) == {"CLOSED": 164, "NON_INSTRUCTION": 2}
    assert markdown_status_counts == csv_status_counts
    assert {status: csv_status_counts.get(status, 0) for status in expected_counts} == expected_counts

