def test_completion_report_identity_mapped_markdown_sections_are_ordered_and_unique():
    import subprocess
    from pathlib import Path

    result = subprocess.run(
        ["python3", "tools/isa_standard_completion.py"],
        check=True,
        capture_output=True,
        text=True,
    )
    stdout_paths = [
        Path(text)
        for text in result.stdout.splitlines()[0].removeprefix("wrote ").split(" and ")
    ]
    assert stdout_paths[1] == Path("reports/isa_standard_completion.md")
    report_lines = stdout_paths[1].read_text(encoding="utf-8").splitlines()
    assert report_lines[0] == "# ISA Standard Completion Ledger"
    assert report_lines[2] == "This ledger is the authoritative local checklist for Jasper CPU standard-set closure."
    section_lines = [line for line in report_lines if line.startswith("## ")]
    assert section_lines == ["## Summary", "## Policy", "## Instruction Rows"]
    section_indexes = [report_lines.index(section) for section in section_lines]
    assert section_indexes == sorted(section_indexes)
    assert section_indexes[0] < report_lines.index("| Status | Count |") < section_indexes[1]
    policy_lines = report_lines[section_indexes[1] + 2 : section_indexes[2] - 1]
    assert policy_lines == [
        "- No standard extension is declared complete while any instruction in that extension is `PARTIAL` or `GAP`.",
        "- `RV32I` is closed at executable runtime level, including the `x0` invariant semantic closure.",
        "- `RV32I+GC` is not yet closed because `M/A/F/D/C/Zicsr` still contain `PARTIAL` or `GAP` rows.",
        "- `RV32I+GC+*` is not yet closed because star/noisy parity is not a substitute for every instruction row reaching `CLOSED`.",
    ]
    assert section_indexes[2] < report_lines.index("| Extension | Instruction | Status | Closure | Evidence |")
    assert report_lines.count("## Summary") == 1
    assert report_lines.count("## Policy") == 1
    assert report_lines.count("## Instruction Rows") == 1

