    from collections import Counter
    from pathlib import Path

    result = subprocess.run(
        ["python3", "tools/isa_standard_completion.py"],
        check=True,
        capture_output=True,
        text=True,
    )
    stdout_paths = [
        Path(text)
        for text in result.stdout.splitlines()[0].removeprefix("wrote ").split(" and ")
    ]
    csv_path, markdown_path = stdout_paths
    with csv_path.open(newline="", encoding="utf-8") as handle:
        csv_rows = list(csv.DictReader(handle))
    report_lines = markdown_path.read_text(encoding="utf-8").splitlines()
    header_index = report_lines.index("| Extension | Instruction | Status | Closure | Evidence |")
    markdown_extensions = []
    for line in report_lines[header_index + 2 :]:
        if line.startswith("| ") and line.endswith(" |"):
            parts = [cell.strip() for cell in line.split("|")]
            markdown_extensions.append(parts[1])
    summary_counts = {}
    for line in report_lines[report_lines.index("## Summary") + 1 : report_lines.index("## Policy")]:
        if line.startswith("| ") and line.endswith(" |"):
            parts = [cell.strip() for cell in line.split("|")]
            if parts[1] not in {"Status", "--------"}:
                summary_counts[parts[1]] = int(parts[2])
    expected_extension_counts = {
        "RV32I": 41,
        "M": 8,
        "A": 11,
        "F": 26,
        "D": 26,
        "C": 27,
        "Zbb": 18,
        "Zicsr": 6,
        "Zifencei": 1,
        "Zam": 1,
        "Ztso": 1,
    }
    csv_extension_counts = Counter(row["extension"] for row in csv_rows)
    assert dict(csv_extension_counts) == expected_extension_counts
    assert Counter(markdown_extensions) == csv_extension_counts
    assert sum(expected_extension_counts.values()) == len(csv_rows) == len(markdown_extensions) == 166
    assert sum(summary_counts.values()) == 166

