def test_completion_report_identity_mapped_gc_partition_order_is_stable():
    import csv
    import subprocess
    from pathlib import Path

    result = subprocess.run(
        ["python3", "tools/isa_standard_completion.py"],
        check=True,
        capture_output=True,
        text=True,
    )
    stdout_paths = [
        Path(text)
        for text in result.stdout.splitlines()[0].removeprefix("wrote ").split(" and ")
    ]
    csv_path, markdown_path = stdout_paths
    with csv_path.open(newline="", encoding="utf-8") as handle:
        csv_extensions = [row["extension"] for row in csv.DictReader(handle)]
    report_lines = markdown_path.read_text(encoding="utf-8").splitlines()
    header_index = report_lines.index("| Extension | Instruction | Status | Closure | Evidence |")
    markdown_extensions = []
    for line in report_lines[header_index + 2 :]:
        if line.startswith("| ") and line.endswith(" |"):
            parts = [cell.strip() for cell in line.split("|")]
            markdown_extensions.append(parts[1])
    assert markdown_extensions == csv_extensions
    partition_by_extension = {
        "RV32I": "base",
        "M": "gc",
        "A": "gc",
        "F": "gc",
        "D": "gc",
        "C": "gc",
        "Zicsr": "gc",
        "Zifencei": "gc",
        "Zbb": "star-runtime",
        "Zam": "metadata",
        "Ztso": "metadata",
    }
    partition_sequence = [partition_by_extension[extension] for extension in csv_extensions]
    compact_partitions = [
        partition
        for index, partition in enumerate(partition_sequence)
        if index == 0 or partition_sequence[index - 1] != partition
    ]
    assert compact_partitions == ["base", "gc", "star-runtime", "gc", "metadata"]
    assert partition_sequence[:41] == ["base"] * 41
    assert partition_sequence[41:139] == ["gc"] * 98
    assert partition_sequence[139:157] == ["star-runtime"] * 18
    assert partition_sequence[157:164] == ["gc"] * 7
    assert partition_sequence[164:] == ["metadata"] * 2

