def test_completion_report_identity_mapped_artifacts_are_byte_stable_across_repeated_generation():
    import hashlib
    import subprocess
    from pathlib import Path

    first = subprocess.run(
        ["python3", "tools/isa_standard_completion.py"],
        check=True,
        capture_output=True,
        text=True,
    )
    first_paths = [
        Path(text)
        for text in first.stdout.splitlines()[0].removeprefix("wrote ").split(" and ")
    ]
    first_hashes = {path: hashlib.sha256(path.read_bytes()).hexdigest() for path in first_paths}
    second = subprocess.run(
        ["python3", "tools/isa_standard_completion.py"],
        check=True,
        capture_output=True,
        text=True,
    )
    second_paths = [
        Path(text)
        for text in second.stdout.splitlines()[0].removeprefix("wrote ").split(" and ")
    ]
    second_hashes = {path: hashlib.sha256(path.read_bytes()).hexdigest() for path in second_paths}
    assert first.stdout == second.stdout
    assert first.stderr == second.stderr == ""
    assert first_paths == second_paths == [
        Path("reports/isa_standard_completion.csv"),
        Path("reports/isa_standard_completion.md"),
    ]
    assert first_hashes == second_hashes
    assert first_hashes[first_paths[0]] != first_hashes[first_paths[1]]

