def test_completion_report_identity_mapped_full_row_identity_digest_matches_across_artifacts():
    import csv
    import hashlib
    import subprocess
    from pathlib import Path

    result = subprocess.run(
        ["python3", "tools/isa_standard_completion.py"],
        check=True,
        capture_output=True,
        text=True,
    )
    csv_path, markdown_path = [
        Path(text)
        for text in result.stdout.splitlines()[0].removeprefix("wrote ").split(" and ")
    ]
    with csv_path.open(newline="", encoding="utf-8") as handle:
        csv_identities = [
            "::".join((row["extension"], row["instruction"], row["status"], row["closure"], row["evidence"]))
            for row in csv.DictReader(handle)
        ]
    report_lines = markdown_path.read_text(encoding="utf-8").splitlines()
    header_index = report_lines.index("| Extension | Instruction | Status | Closure | Evidence |")
    markdown_identities = []
    for line in report_lines[header_index + 2 :]:
        if line.startswith("| ") and line.endswith(" |"):
            parts = [cell.strip() for cell in line.split("|")]
            markdown_identities.append("::".join((parts[1], parts[2], parts[3], parts[4], parts[5])))
    csv_digest = hashlib.sha256("\n".join(csv_identities).encode("utf-8")).hexdigest()
    markdown_digest = hashlib.sha256("\n".join(markdown_identities).encode("utf-8")).hexdigest()
