def test_completion_report_identity_mapped_markdown_summary_counts_are_plain_decimal_integers():
    import subprocess
    from pathlib import Path

    result = subprocess.run(
        ["python3", "tools/isa_standard_completion.py"],
        check=True,
        capture_output=True,
        text=True,
    )
    markdown_path = Path(result.stdout.splitlines()[0].removeprefix("wrote ").split(" and ")[1])
    report_lines = markdown_path.read_text(encoding="utf-8").splitlines()
    summary_lines = report_lines[report_lines.index("## Summary") + 4 : report_lines.index("## Policy") - 1]
    expected = [("CLOSED", "164"), ("PARTIAL", "0"), ("GAP", "0"), ("NON_INSTRUCTION", "2")]
    parsed = []
    for line in summary_lines:
        cells = [cell.strip() for cell in line.split("|")[1:-1]]
        assert len(cells) == 2
        status, count_text = cells
        assert count_text.isdecimal()
        assert count_text == "0" or not count_text.startswith("0")
        assert int(count_text) >= 0
        parsed.append((status, count_text))
