            if evidence_part.startswith("test_"):
                assert evidence_part == evidence_part_lower
                assert " " not in evidence_part
                assert "/" not in evidence_part and "\\" not in evidence_part
                assert all(character.islower() or character.isdigit() or character == "_" for character in evidence_part)
            else:
                assert any(keyword in evidence_part_lower for keyword in ("runtime", "semantic", "closure", "tests"))

