    policy_body = report_lines[policy_index + 1 : instruction_index]
    policy_bullets = [line for line in policy_body if line]
    assert len(policy_bullets) == 4
    assert all(line.startswith("- ") for line in policy_bullets)
    assert all(not line.startswith(("  - ", "* ", "|", "#")) for line in policy_bullets)
    assert policy_body == ["", *policy_bullets, ""]
    assert all("|" not in line for line in policy_bullets)

