def test_completion_report_identity_f_d_evidence_grouping_is_structurally_symmetric():
    import csv
    import subprocess
    from pathlib import Path

    result = subprocess.run(
        ["python3", "tools/isa_standard_completion.py"],
        check=True,
        capture_output=True,
        text=True,
    )
    lines = result.stdout.splitlines()
    assert result.stderr == ""
    assert lines == [
        "wrote reports/isa_standard_completion.csv and reports/isa_standard_completion.md",
        "CLOSED=164 PARTIAL=0 GAP=0 NON_INSTRUCTION=2",
    ]
    csv_path, markdown_path = [
        Path(text)
        for text in lines[0].removeprefix("wrote ").split(" and ")
    ]
    with csv_path.open(newline="", encoding="utf-8") as handle:
        csv_rows = [
            (row["extension"], row["instruction"], row["status"], row["closure"], row["evidence"])
            for row in csv.DictReader(handle)
        ]
    report_lines = markdown_path.read_text(encoding="utf-8").splitlines()
    header_index = report_lines.index("| Extension | Instruction | Status | Closure | Evidence |")
    markdown_rows = []
    for line in report_lines[header_index + 2 :]:
        if line.startswith("| ") and line.endswith(" |"):
            parts = [cell.strip() for cell in line.split("|")]
            markdown_rows.append((parts[1], parts[2], parts[3], parts[4], parts[5]))
    assert markdown_rows == csv_rows
    family_sizes = {}
    for extension in ("F", "D"):
        counts = {}
        for row in csv_rows:
            if row[0] == extension:
                family_key = row[4].removeprefix("test_rv32f_standard_").removeprefix("test_rv32d_standard_")
                family_key = family_key.removesuffix("_on_rv32_f_and_star").removesuffix("_on_rv64_d_and_star")
                counts[family_key] = counts.get(family_key, 0) + 1
        family_sizes[extension] = counts
    assert family_sizes["F"] == {
        "flw_fsw_execute": 2,
        "fused_madd_family_execute": 4,
        "add_sub_execute": 2,
        "mul_execute": 1,
        "div_execute": 1,
        "sqrt_execute": 1,
        "fsgnj_sign_injection_execute": 3,
        "min_max_execute": 2,
        "fcvt_w_execute": 2,
        "fmv_bit_moves_execute": 2,
        "compare_execute": 3,
        "fclass_execute": 1,
        "fcvt_s_execute": 2,
    }
    assert family_sizes["D"] == {
        "fld_fsd_execute": 2,
        "fused_madd_family_execute": 4,
        "add_sub_execute": 2,
        "mul_execute": 1,
        "div_execute": 1,
        "sqrt_execute": 1,
        "fsgnj_sign_injection_execute": 3,
        "min_max_execute": 2,
        "fcvt_single_double_execute": 2,
        "compare_execute": 3,
        "fclass_execute": 1,
        "fcvt_word_from_d_execute": 2,
        "fcvt_d_from_word_execute": 2,
    }
    assert sorted(family_sizes["F"].values()) == sorted(family_sizes["D"].values())
    assert sum(family_sizes["F"].values()) == sum(family_sizes["D"].values()) == 26

