def test_completion_report_identity_summary_counts_are_derived_from_table_rows():
    import csv
    import subprocess
    from pathlib import Path

    result = subprocess.run(
        ["python3", "tools/isa_standard_completion.py"],
        check=True,
        capture_output=True,
        text=True,
    )
    lines = result.stdout.splitlines()
    assert result.stderr == ""
    assert lines == [
        "wrote reports/isa_standard_completion.csv and reports/isa_standard_completion.md",
        "CLOSED=164 PARTIAL=0 GAP=0 NON_INSTRUCTION=2",
    ]
    csv_path, markdown_path = [
        Path(text)
        for text in lines[0].removeprefix("wrote ").split(" and ")
    ]
    with csv_path.open(newline="", encoding="utf-8") as handle:
        csv_rows = list(csv.DictReader(handle))
    report_lines = markdown_path.read_text(encoding="utf-8").splitlines()
    header_index = report_lines.index("| Extension | Instruction | Status | Closure | Evidence |")
    markdown_rows = []
    for line in report_lines[header_index + 2 :]:
        if line.startswith("| ") and line.endswith(" |"):
            parts = [cell.strip() for cell in line.split("|")]
            markdown_rows.append(
                {
                    "extension": parts[1],
                    "instruction": parts[2],
                    "status": parts[3],
                    "closure": parts[4],
                    "evidence": parts[5],
                }
            )
    assert markdown_rows == csv_rows
    derived_counts = {status: 0 for status in ["CLOSED", "PARTIAL", "GAP", "NON_INSTRUCTION"]}
    for row in csv_rows:
        derived_counts[row["status"]] += 1
    summary_start = report_lines.index("| Status | Count |")
    summary_rows = report_lines[summary_start + 2 : summary_start + 6]
    summary_counts = {}
    for line in summary_rows:
        parts = [cell.strip() for cell in line.split("|")]
        summary_counts[parts[1]] = int(parts[2])
    stdout_counts = dict(
        token.split("=") for token in lines[1].split()
    )
    assert summary_counts == derived_counts
    assert {key: int(value) for key, value in stdout_counts.items()} == derived_counts
    assert derived_counts == {"CLOSED": 164, "PARTIAL": 0, "GAP": 0, "NON_INSTRUCTION": 2}

