def test_completion_report_identity_stdout_counts_conserve_table_row_totals():
    import csv
    import subprocess
    from pathlib import Path

    result = subprocess.run(
        ["python3", "tools/isa_standard_completion.py"],
        check=True,
        capture_output=True,
        text=True,
    )
    lines = result.stdout.splitlines()
    assert result.stderr == ""
    assert lines == [
        "wrote reports/isa_standard_completion.csv and reports/isa_standard_completion.md",
        "CLOSED=164 PARTIAL=0 GAP=0 NON_INSTRUCTION=2",
    ]
    stdout_counts = {
        key: int(value)
        for key, value in (token.split("=") for token in lines[1].split())
    }
    csv_path, markdown_path = [
        Path(text)
        for text in lines[0].removeprefix("wrote ").split(" and ")
    ]
    with csv_path.open(newline="", encoding="utf-8") as handle:
        csv_rows = list(csv.DictReader(handle))
    report_lines = markdown_path.read_text(encoding="utf-8").splitlines()
    header_index = report_lines.index("| Extension | Instruction | Status | Closure | Evidence |")
    markdown_statuses = []
    for line in report_lines[header_index + 2 :]:
        if line.startswith("| ") and line.endswith(" |"):
            parts = [cell.strip() for cell in line.split("|")]
            markdown_statuses.append(parts[3])
    csv_statuses = [row["status"] for row in csv_rows]
    assert markdown_statuses == csv_statuses
    assert sum(stdout_counts.values()) == len(csv_rows) == len(markdown_statuses) == 166
    assert csv_statuses.count("CLOSED") == stdout_counts["CLOSED"]
    assert csv_statuses.count("NON_INSTRUCTION") == stdout_counts["NON_INSTRUCTION"]
    assert csv_statuses.count("PARTIAL") == stdout_counts["PARTIAL"] == 0
    assert csv_statuses.count("GAP") == stdout_counts["GAP"] == 0
    assert stdout_counts["CLOSED"] + stdout_counts["NON_INSTRUCTION"] == 166

