def test_completion_report_identity_csv_rows_round_trip_without_encoding_drift():
    import csv
    import io
    import subprocess
    from pathlib import Path

    result = subprocess.run(
        ["python3", "tools/isa_standard_completion.py"],
        check=True,
        capture_output=True,
        text=True,
    )
    lines = result.stdout.splitlines()
    assert result.stderr == ""
    assert lines == [
        "wrote reports/isa_standard_completion.csv and reports/isa_standard_completion.md",
        "CLOSED=164 PARTIAL=0 GAP=0 NON_INSTRUCTION=2",
    ]
    csv_path, markdown_path = [
        Path(text)
        for text in lines[0].removeprefix("wrote ").split(" and ")
    ]
    csv_text = csv_path.read_text(encoding="utf-8")
    with csv_path.open(newline="", encoding="utf-8") as handle:
        reader = csv.DictReader(handle)
        fieldnames = reader.fieldnames
        csv_rows = list(reader)
    assert fieldnames == ["extension", "instruction", "status", "closure", "evidence"]
    output = io.StringIO()
    writer = csv.DictWriter(output, fieldnames=fieldnames, lineterminator="\n")
    writer.writeheader()
    writer.writerows(csv_rows)
    assert output.getvalue() == csv_text
    assert len(csv_rows) == 166
    report_lines = markdown_path.read_text(encoding="utf-8").splitlines()
    header_index = report_lines.index("| Extension | Instruction | Status | Closure | Evidence |")
    assert len(report_lines[header_index + 2 :]) == len(csv_rows)

