def test_completion_report_identity_summary_order_matches_stdout_order():
    import csv
    import subprocess
    from pathlib import Path

    result = subprocess.run(
        ["python3", "tools/isa_standard_completion.py"],
        check=True,
        capture_output=True,
        text=True,
    )
    lines = result.stdout.splitlines()
    assert result.stderr == ""
    assert lines == [
        "wrote reports/isa_standard_completion.csv and reports/isa_standard_completion.md",
        "CLOSED=164 PARTIAL=0 GAP=0 NON_INSTRUCTION=2",
    ]
    stdout_pairs = [token.split("=") for token in lines[1].split()]
    csv_path, markdown_path = [
        Path(text)
        for text in lines[0].removeprefix("wrote ").split(" and ")
    ]
    with csv_path.open(newline="", encoding="utf-8") as handle:
        csv_rows = list(csv.DictReader(handle))
    report_lines = markdown_path.read_text(encoding="utf-8").splitlines()
    summary_start = report_lines.index("| Status | Count |")
    summary_rows = report_lines[summary_start + 2 : summary_start + 6]
    assert summary_rows == [
        f"| {status} | {count} |" for status, count in stdout_pairs
    ]
    derived_counts = {status: 0 for status, _count in stdout_pairs}
    for row in csv_rows:
        derived_counts[row["status"]] += 1
    assert [status for status, _count in stdout_pairs] == ["CLOSED", "PARTIAL", "GAP", "NON_INSTRUCTION"]
    assert {status: int(count) for status, count in stdout_pairs} == derived_counts
    assert sum(derived_counts.values()) == len(csv_rows) == 166

