def test_completion_report_identity_extension_block_boundary_sentinels_are_exact():
    import csv
    import subprocess
    from pathlib import Path

    result = subprocess.run(
        ["python3", "tools/isa_standard_completion.py"],
        check=True,
        capture_output=True,
        text=True,
    )
    lines = result.stdout.splitlines()
    assert result.stderr == ""
    assert lines == [
        "wrote reports/isa_standard_completion.csv and reports/isa_standard_completion.md",
        "CLOSED=164 PARTIAL=0 GAP=0 NON_INSTRUCTION=2",
    ]
    csv_path, markdown_path = [
        Path(text)
        for text in lines[0].removeprefix("wrote ").split(" and ")
    ]
    with csv_path.open(newline="", encoding="utf-8") as handle:
        csv_rows = list(csv.DictReader(handle))
    report_lines = markdown_path.read_text(encoding="utf-8").splitlines()
    header_index = report_lines.index("| Extension | Instruction | Status | Closure | Evidence |")
    markdown_rows = []
    for line in report_lines[header_index + 2 :]:
        parts = [cell.strip() for cell in line.split("|")]
        markdown_rows.append(
            {
                "extension": parts[1],
                "instruction": parts[2],
                "status": parts[3],
                "closure": parts[4],
                "evidence": parts[5],
            }
        )
    assert markdown_rows == csv_rows
    boundaries = {
        "RV32I": (0, 40, "CLOSED", "runtime"),
        "M": (41, 48, "CLOSED", "runtime"),
        "A": (49, 59, "CLOSED", "runtime"),
        "F": (60, 85, "CLOSED", "runtime"),
        "D": (86, 111, "CLOSED", "runtime"),
        "C": (112, 138, "CLOSED", "runtime"),
        "Zbb": (139, 156, "CLOSED", "runtime"),
        "Zicsr": (157, 162, "CLOSED", "runtime"),
        "Zifencei": (163, 163, "CLOSED", "runtime"),
        "Zam": (164, 164, "NON_INSTRUCTION", "metadata"),
        "Ztso": (165, 165, "NON_INSTRUCTION", "metadata"),
    }
    for extension, (first, last, status, closure) in boundaries.items():
        assert csv_rows[first]["extension"] == extension
        assert csv_rows[last]["extension"] == extension
        assert csv_rows[first]["status"] == csv_rows[last]["status"] == status
        assert csv_rows[first]["closure"] == csv_rows[last]["closure"] == closure
    assert len(csv_rows) == 166

