def test_completion_report_identity_stdout_summary_tokens_are_parseable_nonnegative_counts():
    import csv
    import subprocess
    from pathlib import Path

    result = subprocess.run(
        ["python3", "tools/isa_standard_completion.py"],
        check=True,
        capture_output=True,
        text=True,
    )
    lines = result.stdout.splitlines()
    assert result.stderr == ""
    assert lines == [
        "wrote reports/isa_standard_completion.csv and reports/isa_standard_completion.md",
        "CLOSED=164 PARTIAL=0 GAP=0 NON_INSTRUCTION=2",
    ]
    tokens = lines[1].split()
    assert tokens == ["CLOSED=164", "PARTIAL=0", "GAP=0", "NON_INSTRUCTION=2"]
    parsed_counts = {}
    for token in tokens:
        assert token.count("=") == 1
        key, value = token.split("=")
        assert key not in parsed_counts
        assert key in {"CLOSED", "PARTIAL", "GAP", "NON_INSTRUCTION"}
        assert value.isdigit()
        parsed_counts[key] = int(value)
    assert parsed_counts == {"CLOSED": 164, "PARTIAL": 0, "GAP": 0, "NON_INSTRUCTION": 2}
    assert all(value >= 0 for value in parsed_counts.values())
    csv_path, markdown_path = [
        Path(text)
        for text in lines[0].removeprefix("wrote ").split(" and ")
    ]
    with csv_path.open(newline="", encoding="utf-8") as handle:
        csv_rows = list(csv.DictReader(handle))
    report_lines = markdown_path.read_text(encoding="utf-8").splitlines()
    header_index = report_lines.index("| Extension | Instruction | Status | Closure | Evidence |")
    assert sum(parsed_counts.values()) == len(csv_rows) == len(report_lines[header_index + 2 :]) == 166

def test_completion_report_identity_markdown_summary_counts_are_parseable_nonnegative_counts():
    import csv
    import subprocess
    from pathlib import Path

    result = subprocess.run(
        ["python3", "tools/isa_standard_completion.py"],
        check=True,
        capture_output=True,
        text=True,
    )
    lines = result.stdout.splitlines()
    assert result.stderr == ""
    assert lines == [
        "wrote reports/isa_standard_completion.csv and reports/isa_standard_completion.md",
        "CLOSED=164 PARTIAL=0 GAP=0 NON_INSTRUCTION=2",
    ]
    stdout_counts = {
        key: int(value)
        for key, value in (token.split("=") for token in lines[1].split())
    }
    csv_path, markdown_path = [
        Path(text)
        for text in lines[0].removeprefix("wrote ").split(" and ")
    ]
    with csv_path.open(newline="", encoding="utf-8") as handle:
        csv_rows = list(csv.DictReader(handle))
    report_lines = markdown_path.read_text(encoding="utf-8").splitlines()
    summary_start = report_lines.index("| Status | Count |")
    summary_counts = {}
    for line in report_lines[summary_start + 2 : summary_start + 6]:
        assert line.startswith("| ") and line.endswith(" |")
        parts = [cell.strip() for cell in line.split("|")]
        assert len(parts) == 4
        status, count = parts[1], parts[2]
        assert status not in summary_counts
        assert status in {"CLOSED", "PARTIAL", "GAP", "NON_INSTRUCTION"}
        assert count.isdigit()
        summary_counts[status] = int(count)
    assert summary_counts == stdout_counts
    assert all(value >= 0 for value in summary_counts.values())
    derived_counts = {status: 0 for status in summary_counts}
    for row in csv_rows:
        derived_counts[row["status"]] += 1
    assert derived_counts == summary_counts
    assert sum(summary_counts.values()) == len(csv_rows) == 166

