def test_completion_report_identity_policy_gap_terms_align_with_zero_summary_counts():
    import csv
    import subprocess
    from pathlib import Path

    result = subprocess.run(
        ["python3", "tools/isa_standard_completion.py"],
        check=True,
        capture_output=True,
        text=True,
    )
    lines = result.stdout.splitlines()
    assert result.stderr == ""
    assert lines == [
        "wrote reports/isa_standard_completion.csv and reports/isa_standard_completion.md",
        "CLOSED=164 PARTIAL=0 GAP=0 NON_INSTRUCTION=2",
    ]
    csv_path, markdown_path = [
        Path(text)
        for text in lines[0].removeprefix("wrote ").split(" and ")
    ]
    with csv_path.open(newline="", encoding="utf-8") as handle:
        csv_rows = list(csv.DictReader(handle))
    report_lines = markdown_path.read_text(encoding="utf-8").splitlines()
    summary_start = report_lines.index("| Status | Count |")
    summary_counts = {}
    for line in report_lines[summary_start + 2 : summary_start + 6]:
        cells = [cell.strip() for cell in line.split("|")]
        summary_counts[cells[1]] = int(cells[2])
    policy_start = report_lines.index("## Policy")
    instruction_start = report_lines.index("## Instruction Rows")
    policy_lines = report_lines[policy_start + 2 : instruction_start - 1]
    assert summary_counts["PARTIAL"] == 0
    assert summary_counts["GAP"] == 0
    assert any("PARTIAL" in line and "GAP" in line for line in policy_lines)
    assert any("not counted as complete" in line for line in report_lines[:summary_start])
    assert all(row["status"] not in {"PARTIAL", "GAP"} for row in csv_rows)
    assert all(row["status"] == "NON_INSTRUCTION" for row in csv_rows if row["closure"] == "metadata")
    assert len([row for row in csv_rows if row["closure"] == "runtime"]) == summary_counts["CLOSED"] == 164
    assert len([row for row in csv_rows if row["closure"] == "metadata"]) == summary_counts["NON_INSTRUCTION"] == 2

