    assert len(signatures_by_closure["runtime"]) == 164
    assert len(signatures_by_closure["metadata"]) == 2
    assert signatures_by_closure["runtime"].isdisjoint(signatures_by_closure["metadata"])
    assert all(signature[2:4] == ("CLOSED", "runtime") for signature in signatures_by_closure["runtime"])
    assert all(signature[2:4] == ("NON_INSTRUCTION", "metadata") for signature in signatures_by_closure["metadata"])
    assert len(csv_rows) == 166

