def test_completion_report_identity_full_row_signatures_partition_by_gc_star_metadata():
    import csv
    import subprocess
    from pathlib import Path

    result = subprocess.run(
        ["python3", "tools/isa_standard_completion.py"],
        check=True,
        capture_output=True,
        text=True,
    )
    lines = result.stdout.splitlines()
    assert result.stderr == ""
    assert lines == [
        "wrote reports/isa_standard_completion.csv and reports/isa_standard_completion.md",
        "CLOSED=164 PARTIAL=0 GAP=0 NON_INSTRUCTION=2",
    ]
    csv_path, markdown_path = [
        Path(text)
        for text in lines[0].removeprefix("wrote ").split(" and ")
    ]
    with csv_path.open(newline="", encoding="utf-8") as handle:
        csv_rows = list(csv.DictReader(handle))
    markdown_lines = markdown_path.read_text(encoding="utf-8").splitlines()
    instruction_header = markdown_lines.index("| Extension | Instruction | Status | Closure | Evidence |")
    markdown_rows = []
    for line in markdown_lines[instruction_header + 2 :]:
        cells = [cell.strip() for cell in line.split("|")]
        markdown_rows.append(
            {
                "extension": cells[1],
                "instruction": cells[2],
                "status": cells[3],
                "closure": cells[4],
                "evidence": cells[5],
            }
        )
    assert markdown_rows == csv_rows
    gc_extensions = {"RV32I", "M", "A", "F", "D", "C", "Zicsr", "Zifencei"}
    star_extensions = {"Zbb"}
    metadata_extensions = {"Zam", "Ztso"}
    partitions = {"gc": set(), "star": set(), "metadata": set()}
    for row in csv_rows:
        signature = (
            row["extension"],
            row["instruction"],
            row["status"],
            row["closure"],
            row["evidence"],
        )
        if row["extension"] in gc_extensions:
            partitions["gc"].add(signature)
        elif row["extension"] in star_extensions:
            partitions["star"].add(signature)
        elif row["extension"] in metadata_extensions:
            partitions["metadata"].add(signature)
        else:
            raise AssertionError(row["extension"])
    assert {name: len(signatures) for name, signatures in partitions.items()} == {
        "gc": 146,
        "star": 18,
        "metadata": 2,
    }
    assert partitions["gc"].isdisjoint(partitions["star"])
    assert partitions["gc"].isdisjoint(partitions["metadata"])
    assert partitions["star"].isdisjoint(partitions["metadata"])
    assert sum(len(signatures) for signatures in partitions.values()) == 166

def test_completion_report_identity_gc_star_metadata_index_ranges_are_exact():
    import csv
    import subprocess
    from pathlib import Path

    result = subprocess.run(
        ["python3", "tools/isa_standard_completion.py"],
        check=True,
        capture_output=True,
        text=True,
    )
    lines = result.stdout.splitlines()
    assert result.stderr == ""
    assert lines == [
        "wrote reports/isa_standard_completion.csv and reports/isa_standard_completion.md",
        "CLOSED=164 PARTIAL=0 GAP=0 NON_INSTRUCTION=2",
    ]
    csv_path, markdown_path = [
        Path(text)
        for text in lines[0].removeprefix("wrote ").split(" and ")
    ]
    with csv_path.open(newline="", encoding="utf-8") as handle:
        csv_rows = list(csv.DictReader(handle))
    markdown_lines = markdown_path.read_text(encoding="utf-8").splitlines()
    instruction_header = markdown_lines.index("| Extension | Instruction | Status | Closure | Evidence |")
    markdown_rows = []
    for line in markdown_lines[instruction_header + 2 :]:
        cells = [cell.strip() for cell in line.split("|")]
        markdown_rows.append(
            {
                "extension": cells[1],
                "instruction": cells[2],
                "status": cells[3],
                "closure": cells[4],
                "evidence": cells[5],
            }
        )
    assert markdown_rows == csv_rows
    gc_extensions = {"RV32I", "M", "A", "F", "D", "C", "Zicsr", "Zifencei"}
    star_extensions = {"Zbb"}
    metadata_extensions = {"Zam", "Ztso"}
    gc_indexes = [index for index, row in enumerate(csv_rows) if row["extension"] in gc_extensions]
    star_indexes = [index for index, row in enumerate(csv_rows) if row["extension"] in star_extensions]
    metadata_indexes = [index for index, row in enumerate(csv_rows) if row["extension"] in metadata_extensions]
    assert gc_indexes == list(range(139)) + list(range(157, 164))
    assert star_indexes == list(range(139, 157))
    assert metadata_indexes == [164, 165]
    assert len(gc_indexes) == 146
    assert len(star_indexes) == 18
    assert len(metadata_indexes) == 2
    assert sorted(gc_indexes + star_indexes + metadata_indexes) == list(range(166))

