def test_completion_report_identity_extension_order_is_unique_and_terminal_metadata_only():
    import csv
    import subprocess
    from pathlib import Path

    result = subprocess.run(
        ["python3", "tools/isa_standard_completion.py"],
        check=True,
        capture_output=True,
        text=True,
    )
    csv_path, markdown_path = [
        Path(text)
        for text in result.stdout.splitlines()[0].removeprefix("wrote ").split(" and ")
    ]
    with csv_path.open(newline="", encoding="utf-8") as handle:
        csv_rows = list(csv.DictReader(handle))
    markdown_lines = markdown_path.read_text(encoding="utf-8").splitlines()
    instruction_header = markdown_lines.index("| Extension | Instruction | Status | Closure | Evidence |")
    markdown_rows = []
    for line in markdown_lines[instruction_header + 2 :]:
        cells = [cell.strip() for cell in line.split("|")]
        markdown_rows.append(
            {
                "extension": cells[1],
                "instruction": cells[2],
                "status": cells[3],
                "closure": cells[4],
                "evidence": cells[5],
            }
        )

    def extension_order(rows):
        order = []
        for row in rows:
            if not order or order[-1] != row["extension"]:
                order.append(row["extension"])
        return order

    expected_order = ["RV32I", "M", "A", "F", "D", "C", "Zbb", "Zicsr", "Zifencei", "Zam", "Ztso"]
    assert extension_order(csv_rows) == expected_order
    assert extension_order(markdown_rows) == expected_order
    assert {row["extension"] for row in csv_rows if row["closure"] == "metadata"} == {"Zam", "Ztso"}
    assert {row["extension"] for row in markdown_rows if row["status"] == "NON_INSTRUCTION"} == {"Zam", "Ztso"}
    assert all(row["closure"] == "runtime" for row in csv_rows if row["extension"] not in {"Zam", "Ztso"})
    assert all(row["status"] == "CLOSED" for row in markdown_rows if row["extension"] not in {"Zam", "Ztso"})

