def test_completion_report_identity_extension_block_status_and_closure_shapes():
    import csv
    import subprocess
    from collections import defaultdict
    from pathlib import Path

    result = subprocess.run(
        ["python3", "tools/isa_standard_completion.py"],
        check=True,
        capture_output=True,
        text=True,
    )
    csv_path, markdown_path = [
        Path(text)
        for text in result.stdout.splitlines()[0].removeprefix("wrote ").split(" and ")
    ]
    with csv_path.open(newline="", encoding="utf-8") as handle:
        csv_rows = list(csv.DictReader(handle))
    markdown_lines = markdown_path.read_text(encoding="utf-8").splitlines()
    instruction_header = markdown_lines.index("| Extension | Instruction | Status | Closure | Evidence |")
    markdown_rows = []
    for line in markdown_lines[instruction_header + 2 :]:
        cells = [cell.strip() for cell in line.split("|")]
        markdown_rows.append(
            {
                "extension": cells[1],
                "instruction": cells[2],
                "status": cells[3],
                "closure": cells[4],
                "evidence": cells[5],
            }
        )

    expected_counts = {
        "RV32I": 41,
        "M": 8,
        "A": 11,
        "F": 26,
        "D": 26,
        "C": 27,
        "Zbb": 18,
        "Zicsr": 6,
        "Zifencei": 1,
        "Zam": 1,
        "Ztso": 1,
    }

    def by_extension(rows):
        grouped = defaultdict(list)
        for row in rows:
            grouped[row["extension"]].append(row)
        return grouped

    csv_grouped = by_extension(csv_rows)
    markdown_grouped = by_extension(markdown_rows)
    assert csv_rows == markdown_rows
    assert {extension: len(rows) for extension, rows in csv_grouped.items()} == expected_counts
    assert {extension: len(rows) for extension, rows in markdown_grouped.items()} == expected_counts
    for extension, rows in csv_grouped.items():
        if extension in {"Zam", "Ztso"}:
            assert {row["status"] for row in rows} == {"NON_INSTRUCTION"}
            assert {row["closure"] for row in rows} == {"metadata"}
        else:
            assert {row["status"] for row in rows} == {"CLOSED"}
            assert {row["closure"] for row in rows} == {"runtime"}

