    markdown_lines = markdown_path.read_text(encoding="utf-8").splitlines()
    instruction_header = markdown_lines.index("| Extension | Instruction | Status | Closure | Evidence |")
    markdown_rows = []
    for line in markdown_lines[instruction_header + 2 :]:
        cells = [cell.strip() for cell in line.split("|")]
        markdown_rows.append(
            {
                "extension": cells[1],
                "instruction": cells[2],
                "status": cells[3],
                "closure": cells[4],
                "evidence": cells[5],
            }
        )
    gc_extensions = {"RV32I", "M", "A", "F", "D", "C", "Zicsr", "Zifencei"}
    star_extensions = {"Zbb"}
    metadata_extensions = {"Zam", "Ztso"}
    gc_rows = [row for row in csv_rows if row["extension"] in gc_extensions]
    star_rows = [row for row in csv_rows if row["extension"] in star_extensions]
    metadata_rows = [row for row in csv_rows if row["extension"] in metadata_extensions]
    assert csv_rows == markdown_rows
    assert len(gc_rows) == 146
    assert len(star_rows) == 18
    assert len(metadata_rows) == 2
    assert len(gc_rows) + len(star_rows) + len(metadata_rows) == len(csv_rows) == 166
    assert {row["status"] for row in gc_rows} == {"CLOSED"}
    assert {row["closure"] for row in gc_rows} == {"runtime"}
    assert {row["status"] for row in star_rows} == {"CLOSED"}
    assert {row["closure"] for row in star_rows} == {"runtime"}
    assert {row["status"] for row in metadata_rows} == {"NON_INSTRUCTION"}
    assert {row["closure"] for row in metadata_rows} == {"metadata"}
    assert [row["extension"] for row in csv_rows[139:157]] == ["Zbb"] * 18
    assert [row["extension"] for row in csv_rows[157:163]] == ["Zicsr"] * 6
    assert [row["extension"] for row in csv_rows[163:164]] == ["Zifencei"]
    assert [row["extension"] for row in csv_rows[164:]] == ["Zam", "Ztso"]

