    instruction_rows_start = instruction_header + 2
    instruction_lines = markdown_lines[instruction_rows_start:]
    assert len(instruction_lines) == len(csv_rows) == 166
    for index, (line, csv_row) in enumerate(zip(instruction_lines, csv_rows)):
        cells = [cell.strip() for cell in line.split("|")]
