def test_completion_report_identity_extension_enum_order_is_canonical_across_artifacts():
    import csv
    import subprocess
    from pathlib import Path

    result = subprocess.run(
        ["python3", "tools/isa_standard_completion.py"],
        check=True,
        capture_output=True,
        text=True,
    )
    csv_path, markdown_path = [
        Path(text)
        for text in result.stdout.splitlines()[0].removeprefix("wrote ").split(" and ")
    ]
    with csv_path.open(newline="", encoding="utf-8") as handle:
        csv_rows = list(csv.DictReader(handle))
    markdown_lines = markdown_path.read_text(encoding="utf-8").splitlines()
    instruction_header = markdown_lines.index("| Extension | Instruction | Status | Closure | Evidence |")
    markdown_rows = []
    for line in markdown_lines[instruction_header + 2 :]:
        cells = [cell.strip() for cell in line.split("|")]
        markdown_rows.append(
            {
                "extension": cells[1],
                "instruction": cells[2],
                "status": cells[3],
                "closure": cells[4],
                "evidence": cells[5],
            }
        )

    def first_seen_extensions(rows):
        seen = []
        for row in rows:
            if row["extension"] not in seen:
                seen.append(row["extension"])
        return seen

    expected_order = ["RV32I", "M", "A", "F", "D", "C", "Zbb", "Zicsr", "Zifencei", "Zam", "Ztso"]
    assert csv_rows == markdown_rows
    assert first_seen_extensions(csv_rows) == expected_order
    assert first_seen_extensions(markdown_rows) == expected_order
    assert [row["extension"] for row in csv_rows[:1]] == ["RV32I"]
    assert [row["extension"] for row in csv_rows[-2:]] == ["Zam", "Ztso"]
    assert result.stdout.splitlines()[1] == "CLOSED=164 PARTIAL=0 GAP=0 NON_INSTRUCTION=2"

