def test_completion_report_identity_generation_is_byte_stable_across_repeated_runs():
    import subprocess
    from pathlib import Path

    first = subprocess.run(
        ["python3", "tools/isa_standard_completion.py"],
        check=True,
        capture_output=True,
        text=True,
    )
    first_csv_path, first_markdown_path = [
        Path(text)
        for text in first.stdout.splitlines()[0].removeprefix("wrote ").split(" and ")
    ]
    first_csv_bytes = first_csv_path.read_bytes()
    first_markdown_bytes = first_markdown_path.read_bytes()

    second = subprocess.run(
        ["python3", "tools/isa_standard_completion.py"],
        check=True,
        capture_output=True,
        text=True,
    )
    second_csv_path, second_markdown_path = [
        Path(text)
        for text in second.stdout.splitlines()[0].removeprefix("wrote ").split(" and ")
    ]
    second_csv_bytes = second_csv_path.read_bytes()
    second_markdown_bytes = second_markdown_path.read_bytes()

    assert first.stderr == second.stderr == ""
    assert first.stdout == second.stdout
    assert first_csv_path == second_csv_path == Path("reports/isa_standard_completion.csv")
    assert first_markdown_path == second_markdown_path == Path("reports/isa_standard_completion.md")
    assert first_csv_bytes == second_csv_bytes
    assert first_markdown_bytes == second_markdown_bytes
    assert first.stdout.splitlines()[1] == "CLOSED=164 PARTIAL=0 GAP=0 NON_INSTRUCTION=2"

def test_completion_report_identity_artifacts_are_utf8_text_without_bom_nul_or_crlf():
    import subprocess
    from pathlib import Path

    result = subprocess.run(
        ["python3", "tools/isa_standard_completion.py"],
        check=True,
        capture_output=True,
        text=True,
    )
    csv_path, markdown_path = [
        Path(text)
        for text in result.stdout.splitlines()[0].removeprefix("wrote ").split(" and ")
    ]
    for path in [csv_path, markdown_path]:
        data = path.read_bytes()
        text = data.decode("utf-8")
        assert data == text.encode("utf-8")
        assert not data.startswith(b"\xef\xbb\xbf")
        assert b"\x00" not in data
        if path.suffix == ".csv":
            assert b"\r\n" in data
            assert data.endswith(b"\r\n")
        else:
            assert b"\r\n" not in data
            assert b"\r" not in data
            assert data.endswith(b"\n")
        assert text.splitlines()
    assert csv_path == Path("reports/isa_standard_completion.csv")
    assert markdown_path == Path("reports/isa_standard_completion.md")
    assert result.stdout.splitlines()[1] == "CLOSED=164 PARTIAL=0 GAP=0 NON_INSTRUCTION=2"

