def test_completion_report_identity_extension_instruction_status_closure_counts_are_consistent():
    import csv
    import subprocess
    from collections import defaultdict
    from pathlib import Path

    result = subprocess.run(
        ["python3", "tools/isa_standard_completion.py"],
        check=True,
        capture_output=True,
        text=True,
    )
    csv_path, markdown_path = [
        Path(text)
        for text in result.stdout.splitlines()[0].removeprefix("wrote ").split(" and ")
    ]
    with csv_path.open(newline="", encoding="utf-8") as handle:
        csv_rows = list(csv.DictReader(handle))
    markdown_lines = markdown_path.read_text(encoding="utf-8").splitlines()
    instruction_header = markdown_lines.index("| Extension | Instruction | Status | Closure | Evidence |")
    markdown_rows = []
    for line in markdown_lines[instruction_header + 2 :]:
        cells = [cell.strip() for cell in line.split("|")]
        markdown_rows.append(
            {
                "extension": cells[1],
                "instruction": cells[2],
                "status": cells[3],
                "closure": cells[4],
                "evidence": cells[5],
            }
        )
    expected_counts = {
        "RV32I": (41, "CLOSED", "runtime"),
        "M": (8, "CLOSED", "runtime"),
        "A": (11, "CLOSED", "runtime"),
        "F": (26, "CLOSED", "runtime"),
        "D": (26, "CLOSED", "runtime"),
        "C": (27, "CLOSED", "runtime"),
        "Zbb": (18, "CLOSED", "runtime"),
        "Zicsr": (6, "CLOSED", "runtime"),
        "Zifencei": (1, "CLOSED", "runtime"),
        "Zam": (1, "NON_INSTRUCTION", "metadata"),
        "Ztso": (1, "NON_INSTRUCTION", "metadata"),
    }
    grouped = defaultdict(list)
    for row in csv_rows:
        grouped[row["extension"]].append(row)
    assert csv_rows == markdown_rows
    assert set(grouped) == set(expected_counts)
    for extension, (count, status, closure) in expected_counts.items():
        rows = grouped[extension]
        assert len(rows) == count
        assert {row["instruction"] for row in rows}
        assert {row["status"] for row in rows} == {status}
        assert {row["closure"] for row in rows} == {closure}
    assert sum(count for count, _, _ in expected_counts.values()) == len(csv_rows) == 166
    assert result.stdout.splitlines()[1] == "CLOSED=164 PARTIAL=0 GAP=0 NON_INSTRUCTION=2"

def test_completion_report_identity_instruction_placeholder_is_metadata_only():
    import csv
    import subprocess
    from collections import Counter
    from pathlib import Path

    result = subprocess.run(
        ["python3", "tools/isa_standard_completion.py"],
        check=True,
        capture_output=True,
        text=True,
    )
    csv_path, markdown_path = [
        Path(text)
        for text in result.stdout.splitlines()[0].removeprefix("wrote ").split(" and ")
    ]
    with csv_path.open(newline="", encoding="utf-8") as handle:
        csv_rows = list(csv.DictReader(handle))
    markdown_lines = markdown_path.read_text(encoding="utf-8").splitlines()
    instruction_header = markdown_lines.index("| Extension | Instruction | Status | Closure | Evidence |")
    markdown_rows = []
    for line in markdown_lines[instruction_header + 2 :]:
        cells = [cell.strip() for cell in line.split("|")]
        markdown_rows.append(
            {
                "extension": cells[1],
                "instruction": cells[2],
                "status": cells[3],
                "closure": cells[4],
                "evidence": cells[5],
            }
        )
    placeholder = "(no new instruction encodings)"
    assert csv_rows == markdown_rows
    assert Counter(row["instruction"] for row in csv_rows)[placeholder] == 2
    assert all(row["instruction"] != placeholder for row in csv_rows if row["closure"] == "runtime")
