    assert [row["extension"] for row in csv_rows if row["instruction"] == placeholder] == ["Zam", "Ztso"]
    assert [row["status"] for row in csv_rows if row["instruction"] == placeholder] == ["NON_INSTRUCTION", "NON_INSTRUCTION"]
    assert result.stdout.splitlines()[1] == "CLOSED=164 PARTIAL=0 GAP=0 NON_INSTRUCTION=2"

