def test_completion_report_identity_stdout_count_tokens_are_canonical_decimal_values():
    import subprocess

    result = subprocess.run(
        ["python3", "tools/isa_standard_completion.py"],
        check=True,
        capture_output=True,
        text=True,
    )
    stdout_lines = result.stdout.splitlines()
    count_tokens = stdout_lines[1].split()
    assert count_tokens == [
        "CLOSED=164",
        "PARTIAL=0",
        "GAP=0",
        "NON_INSTRUCTION=2",
    ]
    parsed = []
    for token in count_tokens:
        name, value = token.split("=")
        assert name in {"CLOSED", "PARTIAL", "GAP", "NON_INSTRUCTION"}
        assert value == "0" or not value.startswith("0")
        assert value.isdecimal()
        parsed.append((name, int(value)))
    assert parsed == [
        ("CLOSED", 164),
        ("PARTIAL", 0),
        ("GAP", 0),
        ("NON_INSTRUCTION", 2),
    ]
    assert sum(value for _, value in parsed) == 166
    assert stdout_lines[0] == "wrote reports/isa_standard_completion.csv and reports/isa_standard_completion.md"

