def test_completion_report_identity_offset_table_derives_canonical_extension_order():
    import csv
    import subprocess
    from pathlib import Path

    result = subprocess.run(
        ["python3", "tools/isa_standard_completion.py"],
        check=True,
        capture_output=True,
        text=True,
    )
    csv_path, markdown_path = [
        Path(text)
        for text in result.stdout.splitlines()[0].removeprefix("wrote ").split(" and ")
    ]
    with csv_path.open(newline="", encoding="utf-8") as handle:
        csv_rows = list(csv.DictReader(handle))
    markdown_lines = markdown_path.read_text(encoding="utf-8").splitlines()
    instruction_header = markdown_lines.index("| Extension | Instruction | Status | Closure | Evidence |")
    markdown_rows = []
    for line in markdown_lines[instruction_header + 2 :]:
        cells = [cell.strip() for cell in line.split("|")]
        markdown_rows.append(
            {
                "extension": cells[1],
                "instruction": cells[2],
                "status": cells[3],
                "closure": cells[4],
                "evidence": cells[5],
            }
        )
    offsets = [
        ("RV32I", 0, 41),
        ("M", 41, 49),
        ("A", 49, 60),
        ("F", 60, 86),
        ("D", 86, 112),
        ("C", 112, 139),
        ("Zbb", 139, 157),
        ("Zicsr", 157, 163),
        ("Zifencei", 163, 164),
        ("Zam", 164, 165),
        ("Ztso", 165, 166),
    ]

    def first_seen(rows):
        order = []
        for row in rows:
            if row["extension"] not in order:
                order.append(row["extension"])
        return order

    expected_order = [extension for extension, _, _ in offsets]
    assert csv_rows == markdown_rows
    assert first_seen(csv_rows) == expected_order
    assert first_seen(markdown_rows) == expected_order
    assert [csv_rows[start]["extension"] for _, start, _ in offsets] == expected_order
    assert [csv_rows[end - 1]["extension"] for _, _, end in offsets] == expected_order
    assert all([row["extension"] for row in csv_rows[start:end]] == [extension] * (end - start) for extension, start, end in offsets)
    assert result.stdout.splitlines()[1] == "CLOSED=164 PARTIAL=0 GAP=0 NON_INSTRUCTION=2"

def test_completion_report_identity_offset_table_derives_status_summary_counts():
    import csv
    import subprocess
    from collections import Counter
    from pathlib import Path

    result = subprocess.run(
        ["python3", "tools/isa_standard_completion.py"],
        check=True,
        capture_output=True,
        text=True,
    )
    stdout_lines = result.stdout.splitlines()
    csv_path, markdown_path = [
        Path(text)
        for text in stdout_lines[0].removeprefix("wrote ").split(" and ")
    ]
    with csv_path.open(newline="", encoding="utf-8") as handle:
        csv_rows = list(csv.DictReader(handle))
    markdown_lines = markdown_path.read_text(encoding="utf-8").splitlines()
    summary_header = markdown_lines.index("| Status | Count |")
    summary_counts = {}
    for line in markdown_lines[summary_header + 2 : summary_header + 6]:
        cells = [cell.strip() for cell in line.split("|")]
        summary_counts[cells[1]] = int(cells[2])
    offsets = [
        (0, 41, "CLOSED", "runtime"),
        (41, 49, "CLOSED", "runtime"),
        (49, 60, "CLOSED", "runtime"),
        (60, 86, "CLOSED", "runtime"),
        (86, 112, "CLOSED", "runtime"),
        (112, 139, "CLOSED", "runtime"),
        (139, 157, "CLOSED", "runtime"),
        (157, 163, "CLOSED", "runtime"),
        (163, 164, "CLOSED", "runtime"),
        (164, 165, "NON_INSTRUCTION", "metadata"),
        (165, 166, "NON_INSTRUCTION", "metadata"),
    ]
    derived_counts = Counter()
    for start, end, status, closure in offsets:
        rows = csv_rows[start:end]
        assert all(row["status"] == status for row in rows)
        assert all(row["closure"] == closure for row in rows)
        derived_counts[status] += end - start
    expected_counts = {"CLOSED": 164, "PARTIAL": 0, "GAP": 0, "NON_INSTRUCTION": 2}
    stdout_counts = {key: int(value) for token in stdout_lines[1].split() for key, value in [token.split("=")]}
    assert {status: derived_counts[status] for status in expected_counts} == expected_counts
    assert summary_counts == expected_counts
    assert stdout_counts == expected_counts
    assert sum(summary_counts.values()) == len(csv_rows) == 166

