def test_completion_report_identity_stdout_counts_are_derived_from_csv_rows():
    import csv
    import subprocess
    from collections import Counter
    from pathlib import Path

    result = subprocess.run(
        ["python3", "tools/isa_standard_completion.py"],
        check=True,
        capture_output=True,
        text=True,
    )
    csv_path = Path(result.stdout.splitlines()[0].removeprefix("wrote ").split(" and ")[0])
    with csv_path.open(newline="", encoding="utf-8") as handle:
        rows = list(csv.DictReader(handle))
    counts = Counter(row["status"] for row in rows)
    expected_stdout = " ".join(
        f"{status}={counts[status]}"
        for status in ["CLOSED", "PARTIAL", "GAP", "NON_INSTRUCTION"]
    )
    assert result.stdout.splitlines()[1] == expected_stdout
    assert counts == {"CLOSED": 164, "NON_INSTRUCTION": 2}
    assert counts["PARTIAL"] == 0
    assert counts["GAP"] == 0
    assert len(rows) == sum(counts.values())

