def test_completion_report_identity_stdout_and_summary_counts_share_csv_source():
    import csv
    import subprocess
    from collections import Counter
    from pathlib import Path

    result = subprocess.run(
        ["python3", "tools/isa_standard_completion.py"],
        check=True,
        capture_output=True,
        text=True,
    )
    csv_path, markdown_path = [
        Path(text)
        for text in result.stdout.splitlines()[0].removeprefix("wrote ").split(" and ")
    ]
    with csv_path.open(newline="", encoding="utf-8") as handle:
        rows = list(csv.DictReader(handle))
    counts = Counter(row["status"] for row in rows)
    status_order = ["CLOSED", "PARTIAL", "GAP", "NON_INSTRUCTION"]
    stdout_counts = []
    for token in result.stdout.splitlines()[1].split():
        status, count = token.split("=")
        stdout_counts.append((status, int(count)))
    markdown_lines = markdown_path.read_text(encoding="utf-8").splitlines()
    summary_header = markdown_lines.index("| Status | Count |")
    summary_counts = []
    for line in markdown_lines[summary_header + 2 : summary_header + 6]:
        cells = [cell.strip() for cell in line.split("|")]
        summary_counts.append((cells[1], int(cells[2])))
    derived_counts = [(status, counts[status]) for status in status_order]
    assert stdout_counts == derived_counts
    assert summary_counts == derived_counts
    assert stdout_counts == summary_counts
    assert sum(count for _, count in derived_counts) == len(rows) == 166

