    with csv_path.open(newline="", encoding="utf-8") as handle:
        rows = list(csv.DictReader(handle))
    expected_offsets = [
        ("RV32I", 0, 41, "CLOSED", "runtime"),
        ("M", 41, 49, "CLOSED", "runtime"),
        ("A", 49, 60, "CLOSED", "runtime"),
        ("F", 60, 86, "CLOSED", "runtime"),
        ("D", 86, 112, "CLOSED", "runtime"),
        ("C", 112, 139, "CLOSED", "runtime"),
        ("Zbb", 139, 157, "CLOSED", "runtime"),
        ("Zicsr", 157, 163, "CLOSED", "runtime"),
        ("Zifencei", 163, 164, "CLOSED", "runtime"),
        ("Zam", 164, 165, "NON_INSTRUCTION", "metadata"),
        ("Ztso", 165, 166, "NON_INSTRUCTION", "metadata"),
    ]
    for extension, start, end, status, closure in expected_offsets:
        block = rows[start:end]
        assert len(block) == end - start
