def test_completion_report_identity_artifact_line_endings_match_content_roles():
    import subprocess
    from pathlib import Path

    result = subprocess.run(
        ["python3", "tools/isa_standard_completion.py"],
        check=True,
        capture_output=True,
        text=True,
    )
    csv_text, markdown_text = result.stdout.splitlines()[0].removeprefix("wrote ").split(" and ")
    csv_bytes = Path(csv_text).read_bytes()
    markdown_bytes = Path(markdown_text).read_bytes()
    assert csv_bytes.startswith(b"extension,instruction,status,closure,evidence\r\n")
    assert markdown_bytes.startswith(b"# ISA Standard Completion Ledger\n\n")
    assert b"\r\n" in csv_bytes
    assert b"\r\n" not in markdown_bytes
