def test_completion_report_identity_extension_set_and_order_are_exact():
    import csv
    import subprocess
    from itertools import groupby
    from pathlib import Path

    result = subprocess.run(
        ["python3", "tools/isa_standard_completion.py"],
        check=True,
        capture_output=True,
        text=True,
    )
    csv_path = Path(result.stdout.splitlines()[0].removeprefix("wrote ").split(" and ")[0])
    with csv_path.open(newline="", encoding="utf-8") as handle:
        rows = list(csv.DictReader(handle))
    expected_order = ["RV32I", "M", "A", "F", "D", "C", "Zbb", "Zicsr", "Zifencei", "Zam", "Ztso"]
    observed_order = [extension for extension, _ in groupby(rows, key=lambda row: row["extension"])]
    observed_set = {row["extension"] for row in rows}
    assert observed_order == expected_order
    assert observed_set == set(expected_order)
    assert len(observed_set) == len(expected_order) == 11
    assert observed_order[:6] == ["RV32I", "M", "A", "F", "D", "C"]
    assert observed_order[6:9] == ["Zbb", "Zicsr", "Zifencei"]
    assert observed_order[9:] == ["Zam", "Ztso"]
    assert all(row["closure"] == "runtime" for row in rows[:164])
    assert all(row["closure"] == "metadata" for row in rows[164:])
    assert result.stdout.splitlines()[1] == "CLOSED=164 PARTIAL=0 GAP=0 NON_INSTRUCTION=2"

