def test_completion_report_identity_policy_zero_gap_claims_match_rows():
    import csv
    import subprocess
    from collections import Counter
    from pathlib import Path

    result = subprocess.run(
        ["python3", "tools/isa_standard_completion.py"],
        check=True,
        capture_output=True,
        text=True,
    )
    csv_path, markdown_path = [
        Path(text)
        for text in result.stdout.splitlines()[0].removeprefix("wrote ").split(" and ")
    ]
    with csv_path.open(newline="", encoding="utf-8") as handle:
        rows = list(csv.DictReader(handle))
    counts = Counter(row["status"] for row in rows)
    markdown_text = markdown_path.read_text(encoding="utf-8")
    policy_line = "- No standard extension is declared complete while any instruction in that extension is `PARTIAL` or `GAP`."
    assert policy_line in markdown_text
    assert counts["PARTIAL"] == 0
    assert counts["GAP"] == 0
    assert all(row["status"] not in {"PARTIAL", "GAP"} for row in rows)
    assert all(row["status"] == "CLOSED" for row in rows if row["closure"] == "runtime")
    assert all(row["status"] == "NON_INSTRUCTION" for row in rows if row["closure"] == "metadata")
    assert result.stdout.splitlines()[1] == "CLOSED=164 PARTIAL=0 GAP=0 NON_INSTRUCTION=2"

