def test_completion_report_identity_policy_keeps_gc_and_star_completion_conservative():
    import csv
    import subprocess
    from pathlib import Path

    result = subprocess.run(
        ["python3", "tools/isa_standard_completion.py"],
        check=True,
        capture_output=True,
        text=True,
    )
    csv_path, markdown_path = [
        Path(text)
        for text in result.stdout.splitlines()[0].removeprefix("wrote ").split(" and ")
    ]
    with csv_path.open(newline="", encoding="utf-8") as handle:
        rows = list(csv.DictReader(handle))
    markdown_text = markdown_path.read_text(encoding="utf-8")
    gc_policy = "- `RV32I+GC` is not yet closed because `M/A/F/D/C/Zicsr` still contain `PARTIAL` or `GAP` rows."
    star_policy = "- `RV32I+GC+*` is not yet closed because star/noisy parity is not a substitute for every instruction row reaching `CLOSED`."
    runtime_extensions = {"RV32I", "M", "A", "F", "D", "C", "Zbb", "Zicsr", "Zifencei"}
    metadata_extensions = {"Zam", "Ztso"}
    assert gc_policy in markdown_text
    assert star_policy in markdown_text
    assert {row["extension"] for row in rows if row["closure"] == "runtime"} == runtime_extensions
    assert {row["extension"] for row in rows if row["closure"] == "metadata"} == metadata_extensions
    assert all(row["status"] != "GAP" for row in rows)
    assert all(row["status"] != "PARTIAL" for row in rows)
    assert "RV32I+GC is complete" not in markdown_text
    assert "RV32I+GC+* is complete" not in markdown_text
    assert result.stdout.splitlines()[1] == "CLOSED=164 PARTIAL=0 GAP=0 NON_INSTRUCTION=2"

