def test_completion_report_identity_stdout_count_line_parse_contract():
    import subprocess

    result = subprocess.run(
        ["python3", "tools/isa_standard_completion.py"],
        check=True,
        capture_output=True,
        text=True,
    )
    count_line = result.stdout.splitlines()[1]
    tokens = count_line.split()
    parsed = []
    for token in tokens:
        assert token.count("=") == 1
        status, count = token.split("=")
        assert count.isdecimal()
        parsed.append((status, int(count)))
    assert parsed == [
        ("CLOSED", 164),
        ("PARTIAL", 0),
        ("GAP", 0),
        ("NON_INSTRUCTION", 2),
    ]
    assert len(tokens) == 4
    assert count_line == "CLOSED=164 PARTIAL=0 GAP=0 NON_INSTRUCTION=2"

