def test_completion_report_identity_generation_row_tuples_stable_across_two_runs():
    import csv
    import subprocess
    from pathlib import Path

    def run_and_collect():
        result = subprocess.run(
            ["python3", "tools/isa_standard_completion.py"],
            check=True,
            capture_output=True,
            text=True,
        )
        csv_path, markdown_path = [
            Path(text)
            for text in result.stdout.splitlines()[0].removeprefix("wrote ").split(" and ")
        ]
        with csv_path.open(newline="", encoding="utf-8") as handle:
            csv_rows = list(csv.DictReader(handle))
        markdown_lines = markdown_path.read_text(encoding="utf-8").splitlines()
        instruction_header = markdown_lines.index("| Extension | Instruction | Status | Closure | Evidence |")
        markdown_tuples = []
        for line in markdown_lines[instruction_header + 2 :]:
            cells = [cell.strip() for cell in line.split("|")]
            markdown_tuples.append((cells[1], cells[2], cells[3], cells[4], cells[5]))
        csv_tuples = [
            (row["extension"], row["instruction"], row["status"], row["closure"], row["evidence"])
            for row in csv_rows
        ]
        return result.stdout, csv_tuples, markdown_tuples

    first_stdout, first_csv_tuples, first_markdown_tuples = run_and_collect()
    second_stdout, second_csv_tuples, second_markdown_tuples = run_and_collect()
    assert first_stdout == second_stdout
    assert first_csv_tuples == second_csv_tuples
    assert first_markdown_tuples == second_markdown_tuples
    assert first_csv_tuples == first_markdown_tuples
