def test_completion_report_identity_runtime_and_metadata_closure_partition_is_exact():
    import csv
    import subprocess
    from collections import Counter
    from pathlib import Path

    result = subprocess.run(
        ["python3", "tools/isa_standard_completion.py"],
        check=True,
        capture_output=True,
        text=True,
    )
    csv_path = Path(result.stdout.splitlines()[0].removeprefix("wrote ").split(" and ")[0])
    with csv_path.open(newline="", encoding="utf-8") as handle:
        rows = list(csv.DictReader(handle))

    runtime_rows = [row for row in rows if row["closure"] == "runtime"]
    metadata_rows = [row for row in rows if row["closure"] == "metadata"]
    assert len(runtime_rows) == 164
    assert len(metadata_rows) == 2
    assert Counter(row["status"] for row in runtime_rows) == Counter({"CLOSED": 164})
    assert Counter(row["status"] for row in metadata_rows) == Counter({"NON_INSTRUCTION": 2})
    assert all(row["evidence"] for row in runtime_rows)
    assert {row["extension"] for row in metadata_rows} == {"Zam", "Ztso"}
    assert all(row["instruction"] == "(no new instruction encodings)" for row in metadata_rows)
    assert Counter((row["status"], row["closure"]) for row in rows) == Counter(
        {("CLOSED", "runtime"): 164, ("NON_INSTRUCTION", "metadata"): 2}
    )


def test_completion_report_identity_extension_count_parity_preserves_runtime_metadata_totals():
    import csv
    import subprocess
    from collections import Counter
    from pathlib import Path

    result = subprocess.run(
        ["python3", "tools/isa_standard_completion.py"],
        check=True,
        capture_output=True,
        text=True,
    )
    csv_path, markdown_path = [
        Path(text)
        for text in result.stdout.splitlines()[0].removeprefix("wrote ").split(" and ")
    ]
    with csv_path.open(newline="", encoding="utf-8") as handle:
        csv_rows = list(csv.DictReader(handle))
    markdown_lines = markdown_path.read_text(encoding="utf-8").splitlines()
    instruction_header = markdown_lines.index("| Extension | Instruction | Status | Closure | Evidence |")
    markdown_extensions = []
    for line in markdown_lines[instruction_header + 2 :]:
        cells = [cell.strip() for cell in line.split("|")]
        markdown_extensions.append(cells[1])

    expected_counts = Counter(
        {
            "RV32I": 41,
            "M": 8,
            "A": 11,
            "F": 26,
            "D": 26,
            "C": 27,
            "Zbb": 18,
            "Zicsr": 6,
            "Zifencei": 1,
            "Zam": 1,
            "Ztso": 1,
        }
    )
    csv_counts = Counter(row["extension"] for row in csv_rows)
    markdown_counts = Counter(markdown_extensions)
    assert csv_counts == markdown_counts == expected_counts
    assert sum(count for extension, count in csv_counts.items() if extension not in {"Zam", "Ztso"}) == 164
    assert csv_counts["Zam"] + csv_counts["Ztso"] == 2


