def test_completion_report_identity_extension_block_spans_are_contiguous_across_artifacts():
    import csv
    import subprocess
    from pathlib import Path

    result = subprocess.run(
        ["python3", "tools/isa_standard_completion.py"],
        check=True,
        capture_output=True,
        text=True,
    )
    csv_path, markdown_path = [
        Path(text)
        for text in result.stdout.splitlines()[0].removeprefix("wrote ").split(" and ")
    ]
    with csv_path.open(newline="", encoding="utf-8") as handle:
        csv_rows = list(csv.DictReader(handle))
    markdown_lines = markdown_path.read_text(encoding="utf-8").splitlines()
    instruction_header = markdown_lines.index("| Extension | Instruction | Status | Closure | Evidence |")
    markdown_extensions = []
    for line in markdown_lines[instruction_header + 2 :]:
        cells = [cell.strip() for cell in line.split("|")]
        markdown_extensions.append(cells[1])

    expected_spans = [
        ("RV32I", 0, 41),
        ("M", 41, 49),
        ("A", 49, 60),
        ("F", 60, 86),
        ("D", 86, 112),
        ("C", 112, 139),
        ("Zbb", 139, 157),
        ("Zicsr", 157, 163),
        ("Zifencei", 163, 164),
        ("Zam", 164, 165),
        ("Ztso", 165, 166),
    ]
    csv_extensions = [row["extension"] for row in csv_rows]
    for extension, start, stop in expected_spans:
        assert csv_extensions[start:stop] == [extension] * (stop - start)
        assert markdown_extensions[start:stop] == [extension] * (stop - start)
    assert [start for _, start, _ in expected_spans] == [0, 41, 49, 60, 86, 112, 139, 157, 163, 164, 165]
    assert expected_spans[-1][2] == len(csv_rows) == len(markdown_extensions) == 166


