    expected_order = ["RV32I", "M", "A", "F", "D", "C", "Zbb", "Zicsr", "Zifencei", "Zam", "Ztso"]

    def first_seen_order(values):
        seen = []
        for value in values:
            if value not in seen:
                seen.append(value)
        return seen

