def test_completion_report_identity_markdown_summary_recounts_instruction_table_statuses():
    import subprocess
    from collections import Counter
    from pathlib import Path

    result = subprocess.run(
        ["python3", "tools/isa_standard_completion.py"],
        check=True,
        capture_output=True,
        text=True,
    )
    markdown_path = Path(result.stdout.splitlines()[0].removeprefix("wrote ").split(" and ")[1])
    markdown_lines = markdown_path.read_text(encoding="utf-8").splitlines()
    summary_header = markdown_lines.index("| Status | Count |")
    summary_counts = {
        line.split("|")[1].strip(): int(line.split("|")[2].strip())
        for line in markdown_lines[summary_header + 2 : summary_header + 6]
    }
    instruction_header = markdown_lines.index("| Extension | Instruction | Status | Closure | Evidence |")
    instruction_statuses = []
    for line in markdown_lines[instruction_header + 2 :]:
        cells = [cell.strip() for cell in line.split("|")]
        instruction_statuses.append(cells[3])

    recounted = Counter(instruction_statuses)
    expected_counts = {"CLOSED": 164, "PARTIAL": 0, "GAP": 0, "NON_INSTRUCTION": 2}
    assert summary_counts == expected_counts
    assert {status: recounted.get(status, 0) for status in expected_counts} == expected_counts
    assert result.stdout.splitlines()[1] == "CLOSED=164 PARTIAL=0 GAP=0 NON_INSTRUCTION=2"


