def test_completion_report_identity_extension_span_counts_sum_to_runtime_and_metadata_totals():
    import csv
    import subprocess
    from collections import Counter
    from pathlib import Path

    result = subprocess.run(
        ["python3", "tools/isa_standard_completion.py"],
        check=True,
        capture_output=True,
        text=True,
    )
    csv_path, markdown_path = [
        Path(text)
        for text in result.stdout.splitlines()[0].removeprefix("wrote ").split(" and ")
    ]
    with csv_path.open(newline="", encoding="utf-8") as handle:
        csv_rows = list(csv.DictReader(handle))
    markdown_lines = markdown_path.read_text(encoding="utf-8").splitlines()
    instruction_header = markdown_lines.index("| Extension | Instruction | Status | Closure | Evidence |")
    markdown_rows = []
    for line in markdown_lines[instruction_header + 2 :]:
        cells = [cell.strip() for cell in line.split("|")]
        markdown_rows.append({"extension": cells[1], "closure": cells[4]})

    expected_counts = Counter(
        {
            "RV32I": 41,
            "M": 8,
            "A": 11,
            "F": 26,
            "D": 26,
            "C": 27,
            "Zbb": 18,
            "Zicsr": 6,
            "Zifencei": 1,
            "Zam": 1,
            "Ztso": 1,
        }
    )
    for rows in (csv_rows, markdown_rows):
        counts = Counter(row["extension"] for row in rows)
        assert counts == expected_counts
        assert sum(counts.values()) == 166
        assert sum(counts[extension] for extension in ["RV32I", "M", "A", "F", "D", "C", "Zbb", "Zicsr", "Zifencei"]) == 164
        assert sum(counts[extension] for extension in ["Zam", "Ztso"]) == 2
        assert Counter(row["closure"] for row in rows) == Counter({"runtime": 164, "metadata": 2})


