def test_completion_report_identity_m_extension_block_is_runtime_closed_across_artifacts():
    import csv
    import subprocess
    from pathlib import Path

    result = subprocess.run(
        ["python3", "tools/isa_standard_completion.py"],
        check=True,
        capture_output=True,
        text=True,
    )
    csv_path, markdown_path = [
        Path(text)
        for text in result.stdout.splitlines()[0].removeprefix("wrote ").split(" and ")
    ]
    with csv_path.open(newline="", encoding="utf-8") as handle:
        csv_rows = list(csv.DictReader(handle))
    markdown_lines = markdown_path.read_text(encoding="utf-8").splitlines()
    instruction_header = markdown_lines.index("| Extension | Instruction | Status | Closure | Evidence |")
    markdown_rows = []
    for line in markdown_lines[instruction_header + 2 + 41 : instruction_header + 2 + 49]:
        cells = [cell.strip() for cell in line.split("|")]
        markdown_rows.append(
            {
                "extension": cells[1],
                "instruction": cells[2],
                "status": cells[3],
                "closure": cells[4],
                "evidence": cells[5],
            }
        )

    m_rows = csv_rows[41:49]
    assert m_rows == markdown_rows
    assert len(m_rows) == 8
    assert [row["instruction"] for row in m_rows] == ["MUL", "MULH", "MULHSU", "MULHU", "DIV", "DIVU", "REM", "REMU"]
    assert all(row["extension"] == "M" for row in m_rows)
    assert all(row["status"] == "CLOSED" for row in m_rows)
    assert all(row["closure"] == "runtime" for row in m_rows)
    assert all(row["evidence"] and "test" in row["evidence"].lower() for row in m_rows)


