def test_completion_report_identity_zifencei_extension_singleton_is_runtime_closed_across_artifacts():
    import csv
    import subprocess
    from pathlib import Path

    result = subprocess.run(
        ["python3", "tools/isa_standard_completion.py"],
        check=True,
        capture_output=True,
        text=True,
    )
    csv_path, markdown_path = [
        Path(text)
        for text in result.stdout.splitlines()[0].removeprefix("wrote ").split(" and ")
    ]
    with csv_path.open(newline="", encoding="utf-8") as handle:
        csv_rows = list(csv.DictReader(handle))
    markdown_lines = markdown_path.read_text(encoding="utf-8").splitlines()
    instruction_header = markdown_lines.index("| Extension | Instruction | Status | Closure | Evidence |")
    fence_line = markdown_lines[instruction_header + 2 + 163]
    cells = [cell.strip() for cell in fence_line.split("|")]
    markdown_row = {
        "extension": cells[1],
        "instruction": cells[2],
        "status": cells[3],
        "closure": cells[4],
        "evidence": cells[5],
    }

    expected_row = {
        "extension": "Zifencei",
        "instruction": "FENCE.I",
        "status": "CLOSED",
        "closure": "runtime",
        "evidence": "test_explicit_zifencei_extensions_execute_on_rv32_and_rv64 / star Zifencei tests",
    }
    assert csv_rows[163] == markdown_row == expected_row
    assert csv_rows[162]["extension"] == "Zicsr"
    assert csv_rows[164]["extension"] == "Zam"
    assert csv_rows[163]["evidence"] and "test" in csv_rows[163]["evidence"].lower()
    assert result.stdout.splitlines()[1] == "CLOSED=164 PARTIAL=0 GAP=0 NON_INSTRUCTION=2"


def test_completion_report_identity_zam_ztso_metadata_singletons_are_exact_across_artifacts():
    import csv
    import subprocess
    from pathlib import Path

    result = subprocess.run(
        ["python3", "tools/isa_standard_completion.py"],
        check=True,
        capture_output=True,
        text=True,
    )
    csv_path, markdown_path = [
        Path(text)
        for text in result.stdout.splitlines()[0].removeprefix("wrote ").split(" and ")
    ]
    with csv_path.open(newline="", encoding="utf-8") as handle:
        csv_rows = list(csv.DictReader(handle))
    markdown_lines = markdown_path.read_text(encoding="utf-8").splitlines()
    instruction_header = markdown_lines.index("| Extension | Instruction | Status | Closure | Evidence |")
    markdown_rows = []
    for line in markdown_lines[instruction_header + 2 + 164 : instruction_header + 2 + 166]:
        cells = [cell.strip() for cell in line.split("|")]
        markdown_rows.append(
            {
                "extension": cells[1],
                "instruction": cells[2],
                "status": cells[3],
                "closure": cells[4],
                "evidence": cells[5],
            }
        )

    expected_evidence = "Extension affects memory model/atomicity rules rather than adding distinct instruction mnemonics"
    expected_rows = [
        {
            "extension": "Zam",
            "instruction": "(no new instruction encodings)",
            "status": "NON_INSTRUCTION",
            "closure": "metadata",
            "evidence": expected_evidence,
        },
        {
            "extension": "Ztso",
            "instruction": "(no new instruction encodings)",
            "status": "NON_INSTRUCTION",
            "closure": "metadata",
            "evidence": expected_evidence,
        },
    ]
    assert csv_rows[164:166] == markdown_rows == expected_rows
    assert csv_rows[163]["extension"] == "Zifencei"
    assert len(csv_rows) == 166
    assert result.stdout.splitlines()[1] == "CLOSED=164 PARTIAL=0 GAP=0 NON_INSTRUCTION=2"


