def test_completion_report_identity_rv32i_gc_aggregate_runtime_blocks_are_closed_across_artifacts():
    import csv
    import subprocess
    from collections import Counter
    from pathlib import Path

    result = subprocess.run(
        ["python3", "tools/isa_standard_completion.py"],
        check=True,
        capture_output=True,
        text=True,
    )
    csv_path, markdown_path = [
        Path(text)
        for text in result.stdout.splitlines()[0].removeprefix("wrote ").split(" and ")
    ]
    with csv_path.open(newline="", encoding="utf-8") as handle:
        csv_rows = list(csv.DictReader(handle))
    markdown_lines = markdown_path.read_text(encoding="utf-8").splitlines()
    instruction_header = markdown_lines.index("| Extension | Instruction | Status | Closure | Evidence |")
    markdown_rows = []
    for line in markdown_lines[instruction_header + 2 : instruction_header + 2 + 139]:
        cells = [cell.strip() for cell in line.split("|")]
        markdown_rows.append(
            {
                "extension": cells[1],
                "instruction": cells[2],
                "status": cells[3],
                "closure": cells[4],
                "evidence": cells[5],
            }
        )

    gc_rows = csv_rows[:139]
    expected_counts = Counter({"RV32I": 41, "M": 8, "A": 11, "F": 26, "D": 26, "C": 27})
    assert gc_rows == markdown_rows
    assert len(gc_rows) == 139
    assert Counter(row["extension"] for row in gc_rows) == expected_counts
    assert all(row["status"] == "CLOSED" for row in gc_rows)
    assert all(row["closure"] == "runtime" for row in gc_rows)
    assert all(row["evidence"] and "test" in row["evidence"].lower() for row in gc_rows)
    assert csv_rows[139]["extension"] == "Zbb"


