def test_completion_report_identity_normalized_instruction_row_digests_match_across_artifacts():
    import csv
    import hashlib
    import subprocess
    from pathlib import Path

    result = subprocess.run(
        ["python3", "tools/isa_standard_completion.py"],
        check=True,
        capture_output=True,
        text=True,
    )
    csv_path, markdown_path = [
        Path(text)
        for text in result.stdout.splitlines()[0].removeprefix("wrote ").split(" and ")
    ]
    with csv_path.open(newline="", encoding="utf-8") as handle:
        csv_rows = list(csv.DictReader(handle))
    markdown_lines = markdown_path.read_text(encoding="utf-8").splitlines()
    instruction_header = markdown_lines.index("| Extension | Instruction | Status | Closure | Evidence |")
    markdown_rows = []
    for line in markdown_lines[instruction_header + 2 :]:
        cells = [cell.strip() for cell in line.split("|")]
        markdown_rows.append(
            {
                "extension": cells[1],
                "instruction": cells[2],
                "status": cells[3],
                "closure": cells[4],
                "evidence": cells[5],
            }
        )

    def digest_rows(rows):
        payload = "\n".join(
            "\t".join(row[field] for field in ["extension", "instruction", "status", "closure", "evidence"])
            for row in rows
        )
        return hashlib.sha256(payload.encode("ascii")).hexdigest()

    assert len(csv_rows) == len(markdown_rows) == 166
    assert csv_rows == markdown_rows
    assert digest_rows(csv_rows) == digest_rows(markdown_rows)
    assert digest_rows(csv_rows) == digest_rows(csv_rows)
    assert result.stdout.splitlines()[1] == "CLOSED=164 PARTIAL=0 GAP=0 NON_INSTRUCTION=2"


def test_completion_report_identity_artifact_byte_digests_are_stable_across_consecutive_generation():
    import hashlib
    import subprocess
    from pathlib import Path

    def generate_and_digest():
        result = subprocess.run(
            ["python3", "tools/isa_standard_completion.py"],
            check=True,
            capture_output=True,
            text=True,
        )
        csv_path, markdown_path = [
            Path(text)
            for text in result.stdout.splitlines()[0].removeprefix("wrote ").split(" and ")
        ]
        csv_bytes = csv_path.read_bytes()
        markdown_bytes = markdown_path.read_bytes()
        return {
            "stdout": result.stdout,
            "csv_digest": hashlib.sha256(csv_bytes).hexdigest(),
            "markdown_digest": hashlib.sha256(markdown_bytes).hexdigest(),
            "csv_size": len(csv_bytes),
            "markdown_size": len(markdown_bytes),
        }

    first = generate_and_digest()
    second = generate_and_digest()

    assert first == second
    assert first["stdout"] == "wrote reports/isa_standard_completion.csv and reports/isa_standard_completion.md\nCLOSED=164 PARTIAL=0 GAP=0 NON_INSTRUCTION=2\n"
    assert first["csv_size"] > 10000
    assert first["markdown_size"] > 12000
    assert len(first["csv_digest"]) == 64
    assert len(first["markdown_digest"]) == 64


