def test_completion_report_identity_extension_transition_windows_are_exact_across_artifacts():
    import csv
    import subprocess
    from pathlib import Path

    result = subprocess.run(
        ["python3", "tools/isa_standard_completion.py"],
        check=True,
        capture_output=True,
        text=True,
    )
    csv_path, markdown_path = [
        Path(text)
        for text in result.stdout.splitlines()[0].removeprefix("wrote ").split(" and ")
    ]
    with csv_path.open(newline="", encoding="utf-8") as handle:
        csv_rows = list(csv.DictReader(handle))
    markdown_lines = markdown_path.read_text(encoding="utf-8").splitlines()
    instruction_header = markdown_lines.index("| Extension | Instruction | Status | Closure | Evidence |")
    markdown_rows = []
    for line in markdown_lines[instruction_header + 2 :]:
        cells = [cell.strip() for cell in line.split("|")]
        markdown_rows.append(
            {
                "extension": cells[1],
                "instruction": cells[2],
                "status": cells[3],
                "closure": cells[4],
                "evidence": cells[5],
            }
        )

    transitions = [
        (40, "RV32I", "x0 invariant", 41, "M", "MUL"),
        (48, "M", "REMU", 49, "A", "LR.W"),
        (59, "A", "AMOMAXU.W", 60, "F", "FLW"),
        (85, "F", "FMV.W.X", 86, "D", "FLD"),
        (111, "D", "FCVT.D.WU", 112, "C", "C.ADDI4SPN"),
        (138, "C", "C.SWSP", 139, "Zbb", "ANDN"),
        (156, "Zbb", "REV8", 157, "Zicsr", "CSRRW"),
        (162, "Zicsr", "CSRRCI", 163, "Zifencei", "FENCE.I"),
        (163, "Zifencei", "FENCE.I", 164, "Zam", "(no new instruction encodings)"),
        (164, "Zam", "(no new instruction encodings)", 165, "Ztso", "(no new instruction encodings)"),
    ]
    for rows in (csv_rows, markdown_rows):
        for left_index, left_extension, left_instruction, right_index, right_extension, right_instruction in transitions:
            assert rows[left_index]["extension"] == left_extension
            assert rows[left_index]["instruction"] == left_instruction
            assert rows[right_index]["extension"] == right_extension
            assert rows[right_index]["instruction"] == right_instruction
    assert csv_rows == markdown_rows


