def test_completion_report_extension_order_and_block_lengths_are_identical_across_artifacts():
    import csv
    import subprocess
    from itertools import groupby
    from pathlib import Path

    result = subprocess.run(
        ["python3", "tools/isa_standard_completion.py"],
        check=True,
        capture_output=True,
        text=True,
    )
    csv_path, markdown_path = [
        Path(text)
        for text in result.stdout.splitlines()[0].removeprefix("wrote ").split(" and ")
    ]
    with csv_path.open(newline="", encoding="utf-8") as handle:
        csv_rows = list(csv.DictReader(handle))
    markdown_lines = markdown_path.read_text(encoding="utf-8").splitlines()
    instruction_header = markdown_lines.index("| Extension | Instruction | Status | Closure | Evidence |")
    markdown_rows = []
    for line in markdown_lines[instruction_header + 2 :]:
        cells = [cell.strip() for cell in line.split("|")]
        markdown_rows.append({"extension": cells[1], "instruction": cells[2]})

    expected_blocks = [
        ("RV32I", 41),
        ("M", 8),
        ("A", 11),
        ("F", 26),
        ("D", 26),
        ("C", 27),
        ("Zbb", 18),
        ("Zicsr", 6),
        ("Zifencei", 1),
        ("Zam", 1),
        ("Ztso", 1),
    ]

    for rows in (csv_rows, markdown_rows):
        actual_blocks = [
            (extension, sum(1 for _ in group))
            for extension, group in groupby(row["extension"] for row in rows)
        ]
        assert actual_blocks == expected_blocks
    assert [(row["extension"], row["instruction"]) for row in csv_rows] == [
        (row["extension"], row["instruction"]) for row in markdown_rows
    ]
